window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["30136334"]={"book":{"id":30136334,"title":"自信力：成为最好的自己（第三版）","author":"【英】罗布.杨（Rob Yeung）","translator":"寇彧","publisher":"人民邮电出版社","pubdate":"2018-2","isbn":"9787115473547","tags":["自信","心理学","心理","quickbite"],"memCount":null},"np":1,"pb":[8],"idx":[{"i":14043,"t":"建立自信三方法和将无效的担忧转化为有效的面对方案","l":"TF3-3","c":"ivywang","g":1,"p":1},{"i":13827,"t":"将无效的担忧转化为有效的面对方案","l":"TF3-2","c":"ivywang","g":1,"p":1},{"i":13705,"t":"将无效的担忧转化为有效的面对方案","l":"TF3-2","c":"ivywang","g":1,"p":1},{"i":13225,"t":"主动采取行动，为自己人生带来改变。","l":"TF3-1","c":"ivywang","g":1,"p":1},{"i":12874,"t":"主动采取行动，为自己人生带来改变。","l":"TF3-1","c":"ivywang","g":1,"p":1},{"i":12361,"t":"从舒适圈跨出对生活和工作的自我反思并以自评方式找到人生想专注的三领域;当遇到挫折时,能够当人生的自我教练,来让自信心充满","l":"TF2-4","c":"ivywang","g":1,"p":1},{"i":12167,"t":"从舒适圈跨出对生活和工作的自我反思并以自评方式找到人生想专注的三领域;当遇到挫折时,能够当人生的自我教练,来让自信心充满","l":"TF2-4","c":"ivywang","g":1,"p":1},{"i":11872,"t":"腹式呼吸","l":"TF2-1","c":"海川","g":1,"p":1}],"ms":[{"id":14043,"topic":"建立自信三方法和将无效的担忧转化为有效的面对方案","learn_goal":"","remark":"学习者能运用“自信力三方法”和“三来医师“建立自信心和有效面对无效担忧的行动","level":"TF3-3","duration":80,"status":30,"type":0,"chaishujia":{"username":"ivywang","city":""},"club":{"name":"台北悦读不卡分舵","city":"台北"},"prologue":"\u003cp>\u003cstrong>【开场+分组】 \u003c/strong>\u003c/p>\u003cp>大家好，我是IVY，来自台湾台北的王靖蕙。现为二级拆书家。我的三个标签：劲量电池丶开创行者丶可视化卡片达人,欢迎参加我的TF3-3练级场。现在分组一下,就依现场的人数，自成一组。\u003c/p>\u003ch1>\u003cstrong>【场景介绍法】\u003c/strong>\u003c/h1>\u003cul>\u003cli>\u003cstrong>【事件】\u003c/strong>\u003c/li>\u003c/ul>\u003cp>请大家想像一个场景，每天一起床,总是无力感很重,不想去上班,总想著许多的藉口,幻想著能请假,不去上班该有多好;又或者对自己很没有动力,感到在上班中的自己,能力很差劲。\u003c/p>\u003cul>\u003cli>\u003cstrong>【提問】\u003c/strong>\u003c/li>\u003c/ul>\u003cp>请问大家,往往出现这样的想法,通常是什麽情况下呢?\u003c/p>\u003cp>学习者：有，没有不想的\u003c/p>\u003cp>拆书家：相信这样的经验我们都曾有过\u003c/p>\u003cul>\u003cli>\u003cstrong>【影响】\u003c/strong>\u003c/li>\u003c/ul>\u003cp>像这样不想上班的情况，如果我们不去看清背后的真正原因，上起班来就会一直活在自我怀欵中，工作展现不好，人也不开心,在工作中效率低下，总是被领导或同事批评和指责，每天疲于奔命地陷入一事无成的恶性循环，甚至导致人生无望的自我放弃。\u003c/p>\u003cul>\u003cli>\u003cstrong>【解決】\u003c/strong>\u003c/li>\u003c/ul>\u003cp>本书将帮助读者找回对自我的自信心，用有效且易执行的行动方案,重拾面对苦闷或困惑时的自信态度。\u003c/p>\u003cp>\u003cstrong>【拆頁一学习目标】\u003c/strong>\u003c/p>\u003cp>学习者跟我完成拆页一的现场学习，能根据「自信心」(澄清)方法，在面对信心不足的心态下,制定出(行为)改善负面想法的行动方案(界定)\u003c/p>","ratings_count":2,"texts":[{"id":18057,"quote":"\u003cp>接下来我们花一分钟的时间,来看本次的拆页内容，來自《自信力：成为最好的自己（第3版）》微信電子書 P72\u003c/p>\u003cp>[主题]：沒自信多數是因為想法不對\u003c/p>\u003cp>[片段来源]：《自信力：成为最好的自己（第3版）》微信電子書 P72\u003c/p>\u003cp>自信是一种智力游戏，它和人的高矮、性别、年龄等生理特征无关。自信的人都相信自己，而正因为相信自己，他们才能成功。所以，何不花点时间问问自己：“我通常是用什么样的信息来支持自己的？”你常告诉自己“我很强壮、很聪明、很有自信”吗？还是会沉湎于自己的错误、弱点和失败呢？其实，无论你现在的心态如何，你都可以有意识地通过改变看待自我和世界的方式来迅速提升自信力，并利用一些技巧进行更积极乐观、更有建设性的思考。\u003c/p>","explains":"\u003ch2>\u003cstrong>【提问互动】\u003c/strong>\u003c/h2>\u003cp>拆书家：大家都看完這個拆頁後,自信心和什麼無關?\u003c/p>\u003cp>学习者：高矮丶性別丶年齡\u003c/p>\u003cp>拆书家：很好,当面对没有自信心时,我们可以通过有意识?还是无意识?来提升自信力呢?\u003c/p>\u003cp>学习者：有意识的方式\u003c/p>\u003cp>拆书家：是的,大家对拆页都掌握的很好,用有意识地通过改变看待自我和世界的方式来提升自信力\u003c/p>\u003ch2>\u003cstrong>【What】\u003c/strong>\u003c/h2>\u003cp>从原文中我们知道,自信心和外在相貌和年龄等无关,那什麽是自信心呢?自信是一种对自我的相信和肯定,愿意用这样的心态和想法,来看待自己。\u003c/p>\u003ch2>\u003cstrong>【Why】\u003c/strong>\u003c/h2>\u003cp>为什麽自信心如此重要?有自信的人,会对事件的看法,是一种正面和积极的态度,不会逃避,而是会勇于面对,相反地,没有自信的人,就易鑽牛角尖,面对问题丶事情,就易退缩,行为和心态,都负面的较多。\u003c/p>\u003cp>为了让大家更易了解自信心的重要性,下面举几个例子，让大家判断一下,是否有自信心?\u003c/p>\u003ch2>\u003cstrong>【对比概念，案例折返引出逻辑、步骤】\u003c/strong>\u003c/h2>\u003cp>【反例 1 】大美一早起床,心情還停留在昨天被主管指出文件出錯的情景,想到主管的嘴臉,以及覺得主管很愛找茬，又不想去上班了\u003c/p>\u003cp>【拆书家】： 請問大美的状态,是一種自信的展現嗎?\u003c/p>\u003cp>【学习者】：不是\u003c/p>\u003cp>【拆书家】：為什麼你覺得大美不夠有自信呢?\u003c/p>\u003cp>【学习者】：因為他覺得被人指出,文件出錯以及他想逃避不想去上班\u003c/p>\u003cp>【拆书家】：是的,回答的非常好,大美面对昨天被主管指出错误,心情仍停留在昨天的挫折中,没有对自我转念，改变态度，只想一昧逃避。\u003c/p>\u003cp>【反例 2】如果大美学著转念，心想主管指骂，就像一份礼物一样，要开心接纳，对著自己如此说后，虽然心态好多了，但对昨天的错误，也没有盘点一翻，在工作上小心翼翼，还是犯错又被主管骂\u003c/p>\u003cp>【拆书家】：请问大美的小心翼翼是一种自信的展现吗?\u003c/p>\u003cp>【学习者】：不太像\u003c/p>\u003cp>【拆书家】：为什么你觉得大美仍不够有自信呢?\u003c/p>\u003cp>【学习者】：因为她太小心了,还带著挫折的过往,这样上班,只会更加犯错\u003c/p>\u003cp>【拆书家】：是的,回答的很好,大美不知犯错的地方，要自我检讨，同时记录下易犯错的点，自我提醒，反而在工作上小心翼翼，这样是没有用有自信心的态度去面对的。\u003c/p>\u003cp>【正例 3】如果大美对主管的指责,能用\u003c/p>\u003cp>1.是主管给他的成长礼物\u003c/p>\u003cp>2.将主管指骂的要点,记录下来,提醒自己注意\u003c/p>\u003cp>3.回家后,经过反思后,对自我一份激励&quot;我可以做到&quot;&quot;我可以不二过&quot;的自我肯定喊话\u003c/p>\u003cp>隔天用这样的心态和自我肯定去上班\u003c/p>\u003cp>【拆书家】：请问大家,觉不觉得大美是不是一位具有积极想法和行动的人\u003c/p>\u003cp>【学习者】：是的\u003c/p>\u003cp>【拆书家】：人没有不犯错的,能在犯错丶挫折丶失败,获取经验,同时转变想法,用积极乐观态度去面对,如此一来,大美就能越来越有自信,相信在工作上的表现,也会越来越好。\u003c/p>\u003ch2>\u003cstrong>【How】\u003c/strong>\u003c/h2>\u003cp>根据刚才的例子讲解，我们可以总结建立自信的三方法：\u003c/p>\u003cp>1.转—转变态度：学著转弯,用另一角度看待事情的发生,视人生的挫折或不如意,都是老天爷给你的礼物,因为你是巧木,可以雕塑,才有此考验。\u003c/p>\u003cp>2.记—记录要点：记录下犯错的原因出在何处?找到问题点。唯有经过自我反思,才会有印象,记录才能提醒自己不再犯同样的过错。\u003c/p>\u003cp>3.励—自我激励：对自我喊话，相信自己可以做到。相信好话是有力量的,当你说出自我激励和肯定的话语,无形中,已提升自我信心。\u003c/p>\u003ch2>\u003cstrong>【预防异议】\u003c/strong>\u003c/h2>\u003cp>有人可能会觉得，被骂就被骂丶失败就失败丶不如意就不如意，反正我这个人做什麽事都不成功，学这个建立自信三方法做什麽？若你有此想法，就是一种不自信的展现了，这时侯，这个方法就非常值得一用，因为想法会改变我们看法世界的看法，也会带来对自己人生的不同道路，不可不慎呀！\u003c/p>\u003ch2>\u003cstrong>【Where】(适用场景)\u003c/strong>\u003c/h2>\u003cp>适用在想建立自我信心的人身上，并不适合没有心想改变自己和人生观的人身上\u003c/p>","interaction":"\u003ch1>\u003cstrong>【A2 】催化应用 \u003c/strong>\u003c/h1>\u003cp>【显像提问】（编故事）\u003c/p>\u003cp>接下來，我们依照今天所學的建立自信三方法，来做一个练习，请大家自己编一个未来一周内带给你负面情绪或不自信的場景，需要包括故事背景（时间、地点、人物），情节变化（起因、经过、结果），人物的动作和对话等。提醒大家,记得记录对话内容,若是只有自己,人物,就写自己。\u003c/p>\u003cp>时间到了，那下面我们请学习者代表来分享所写的剧本，时间2分钟。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【点评与总结】\u003c/strong>\u003c/p>\u003cp>非常好,将自我对话的转记励运用的很好,不论好的丶坏的,都能用正向态度来看待,不是只沉沦在负面情绪，达到好的，可以更好，坏的也没有想像中的差，恭喜你在此方法，圆满工作报告。\u003c/p>\u003cp>\u003cstrong>【片段间逻辑间关係】\u003c/strong>\u003c/p>\u003cp>我们知道了，建立自信的三方法，转变态度丶记录要点丶自我激励，信心是有了，但心情和面对未知或者没有挑战过的事，总会不够自信，这时我们就可以进一步，运用拆页二的三来方法，帮助我们对无效的担忧转化为有效的面对方案。拆页一和拆页二的关係属于逻辑递进关係。\u003c/p>\u003ch2>【A1：量表自测】\u003c/h2>\u003cp>为了让大家更好地了解自己的担忧程度，下面请先来完成几道自测题，按照1-5的标准给自己打分，1分代表完全不符合，5分代表完全符合，请用1分钟的时间完成，并完成分数统计。做好的小伙伴示意一下。\u003c/p>\u003ch2>\u003c/h2>\u003ch2>\u003cstrong>【自測量表解釋】\u003c/strong>\u003c/h2>\u003cp>请各位对照一下自己的得分。\u003c/p>\u003cp>得分在10分以下，代表你的内心很平静，在此次学完拆页后,能有更好的表现哦;\u003c/p>\u003cp>得分在11-20分，要稍稍注意一下,自己的担忧,找到方法好好面对它。\u003c/p>\u003cp>得分在21分以上，你真的来对了,今天的学习,会对你很有帮助哦。\u003c/p>\u003cp>在此声明一下\u003c/p>\u003cp>自测题不是用来放大负面情绪或者否定自我，而是用来帮助大家清楚看到内心状态,进而面对问题,获得心情平静。\u003c/p>\u003ch2> \u003c/h2>\u003cp>\u003cstrong>【拆頁二学习目标】\u003c/strong>\u003c/p>\u003cp>学习者在跟随我完成RIA现场学习后，学习者能够运用三来,记下来丶分类来丶做出来，能够将无效的担忧转化为有效的面对方案。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}},{"id":18058,"quote":"\u003cp>接下来我们花一分钟的时间,来看本次的拆页内容，來自《自信力：成为最好的自己（第3版）》微信電子書 P123\u003c/p>\u003cp>你有没有想过究竟什么是担忧？心理学家认为担忧是对未来可能出现的差错的一种无效的忧虑，令你担忧的事情可能包括被拒绝、失败、染上疾病或者遭遇车祸等。你会坐立不安，不停地思考“如果发生了这种事该怎么办？”“如果出了问题该怎么办？”然后你会想：“我无法应对这些事情！”\u003c/p>\u003cp>过度担忧的人不愿意停止担忧，因为他们（无意识地）相信考虑最坏的情况有助于他们做好准备。然而，心理学家发现在大多数情况下，我们的担忧实际上不能帮助我们有效地解决问题或者为未来做好准备。\u003c/p>\u003cp>大多数过度担忧的人没有思考过他们在担忧的时候做了什么。他们可能将自己的担忧视为“深谋远虑”或者“未雨绸缪”。因此为了减轻你的担忧，你要做的第一步就是记录你的担忧。在接下来的四个星期里，你要随身携带便签本，随时随地记录下你的担忧。\u003c/p>\u003cp>如何确定自己是否正在产生担忧？下面是关于担忧的常见信号。\u003c/p>\u003cp>·一遍又一遍地思考“如果发生了……”或者“噢，怎么会这样”之类的问题。\u003c/p>\u003cp>·思考不在你的能力控制范围之内的事情。\u003c/p>\u003cp>·关注最糟糕的事情，但实际上没有证据表明这些事情可能会发生。\u003c/p>\u003cp>每次你担忧某事时，就记录下当时的日期和时间，你担忧什么，以及你的担忧持续了多久。\u003c/p>","explains":"\u003cp>【拆书家】大家看完这个拆页后,有人愿意分享一下是什麽内容?\u003c/p>\u003cp>【学习者】讲述担忧实际上不能帮助我们有效地解决问题或为未来做好准备。\u003c/p>\u003cp>【拆书家】拆页中,提到遇到担心时,会不停的想那三句话？\u003c/p>\u003cp>【学习者】\u003c/p>\u003cp>“如果发生了这种事该怎么办？”\u003c/p>\u003cp>“如果出了问题该怎么办？”\u003c/p>\u003cp>&quot;我无法应对这些事情！”\u003c/p>\u003cp>【拆书家】太好了,大家对拆页的内容都掌握的非常好!\u003c/p>\u003ch2>\u003cstrong>【What】\u003c/strong>\u003c/h2>\u003cp>担忧是一种心理因素,人会做出一些心理尝试以防止受到潜在的威胁,任何人不免都有此心理存在。\u003c/p>\u003ch2>\u003cstrong>【Ｗhy】\u003c/strong>\u003c/h2>\u003cp>为什麽我们要面对担忧丶了解担忧呢?常担忧的人, 容易吃不好、睡不好丶爱发呆丶爱生气,无法享受真正的生活;担忧太过会使我们对未来不抱希望,严重还会致癌。为了有一个美好人生,我们要正视我们的心理因素,找到面对的办法。\u003c/p>\u003ch2>\u003cstrong>【How具體步驟】\u003c/strong>\u003c/h2>\u003cp> 如何做?三来,记下来丶分类来丶做出来\u003c/p>\u003cp>1.记：简单记下来\u003c/p>\u003cp>把所担忧的事，简单寫下关键字来,让心中的烦恼丝能够抽丝剥茧\u003c/p>\u003cp>2.类：分出三类来\u003c/p>\u003cp>在所烦恼的众多烦恼丝，分出你觉得的三类程度来\u003c/p>\u003cp>最在乎：感到最担心的情绪\u003c/p>\u003cp>尚可以：介于在乎和不在乎之间\u003c/p>\u003cp>在乎低：觉这件事有转机，也没有自己想像中的担忧\u003c/p>\u003cp>3.做：尽力做出来\u003c/p>\u003cp>对最糟糕的事，尽力想出解决方案，最好多想几个，最少三个，找一个最简单又易行的去做。\u003c/p>\u003ch2>\u003cstrong>【舉例】\u003c/strong>\u003c/h2>\u003cp>案主：IVY\u003c/p>\u003cp>事件：上台演讲\u003c/p>\u003cp>时间：上个月的某一週日\u003c/p>\u003cp>地点：课堂上\u003c/p>\u003cp>对象：台下的众多老师们\u003c/p>\u003cp>背景：\u003c/p>\u003cp>上周日因要上台分享，知道讲台下坐的都是大佬，心情莫名担忧怕自己表现不好，美食当前也吃不下，熬夜又早起，像极了洩了气的汽球；心情很容易感伤，虽出大太阳，感觉是下雨了。\u003c/p>\u003cp>于是我用了三来的方法，梳理自己心中的担忧。\u003c/p>\u003ch2>\u003cstrong>【预防异议】\u003c/strong>\u003c/h2>\u003cp>也许有人会觉得,这个三来方法看起来,有跟没有,没什麽差别!!若你这样想,可能就失去了一个可以观照自己的好机会;相信当人一担忧时,头脑是无法思考的,过度还会紧张无措,不知怎麽办。有一个好方法,让我们面对担忧,可说是,当自己的心理医师了。\u003c/p>\u003ch2>\u003cstrong>【适用边界】\u003c/strong>\u003c/h2>\u003cp>适用在当你感到担忧时或常动不动就担忧的人身上,若本身很开心,就不适宜用此方法。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】微行動學習 \u003c/strong>\u003c/p>\u003cp>【明确问题】\u003c/p>\u003cp>请大家先回想一下,你曾经对自己不自信的场景或事件,在心中默默地写下来,并且对照今天所说的三来医师的方法,先在心中,自我预演一下,给大家1分钟,好的小伙伴,同我示意一下\u003c/p>\u003cp>经过刚刚的自我预演,面对三来医师的方法,那一个步骤,你会觉得在运用上有困难的?\u003c/p>\u003cp>给大家3分钟的时间在小组内讨论，之后我们邀请\u003cu>两位\u003c/u>进行分享。\u003c/p>\u003cp>【小伙伴分享】\u003c/p>\u003cp>时间到，请跟大家分享一下你们讨论的结果。\u003c/p>\u003cp>代表：我认为第3步：做出来\u003c/p>\u003cp>【回应和反馈】\u003c/p>\u003cp>谢谢大家，我们很快地，就达到意见统一的部份，都认为是做出来，比较困难。不用举手表决，也不用猜拳。\u003c/p>\u003ch4>【1.重述并明确问题】\u003c/h4>\u003cp>經過大家的討論，我们下面就一起讨论关于＂做出来＂这个方法，對嗎？\u003c/p>\u003cp>学习者：是的。\u003c/p>\u003ch4>【2.引导分组讨论问题的本质】\u003c/h4>\u003cp>【提问式反馈与回应】\u003c/p>\u003cp>好，我们就请小伙伴们在组内开展讨论，大家要结合自己的经验来探讨：为什么我们会觉得＂做出来＂\u003cstrong>是一件困难的事情\u003c/strong>？请写下\u003cstrong>三个原因\u003c/strong>，它具体困难在哪里？给大家5分钟的讨论时间，请记录一下小组讨论的结果，待會請小伙伴代表來分享。\u003c/p>\u003cp>【学员讨论】\u003c/p>\u003cp>Carol觉得困难的原因,分成四象限：\u003c/p>\u003cp>1. 知道做到，知道到做到，做到就代表做出来了；\u003c/p>\u003cp>2.怕的是知道但做不到； \u003c/p>\u003cp>3.不知道也不会做\u003c/p>\u003cp>4. 不知道，后来知道了，会去做的\u003c/p>\u003cp>小小觉得困难的原因：\u003c/p>\u003cp>1.做到但不成功?\u003c/p>\u003cp>2.做到要是成功的?\u003c/p>\u003cp>3.认为要成功才能减少担忧\u003c/p>\u003cp>Carol:若做到但不成功的结果,却对自己有用,是不是也是一种成功呢?,认为应以自己为出发点,从自己知道且做得到的为主;若再好的方法,对自己没用,也是不成功\u003c/p>\u003cp>小小:对\u003c/p>\u003cp>Carol:那我们应该以个人来讲,知道同时也做得到的方向来讨论。如疫情药剂,虽然知道有,但买不到(做),一样是担心。\u003c/p>\u003cp>小小:要在能力圈范围。经验有限和能力有限的原因。\u003c/p>\u003cp>Carol:要做出来,第一个经验要够,第二个就是我的能力要足。\u003c/p>\u003cp>小小:对对对\u003c/p>\u003ch4>【3.明确问题的本质】\u003c/h4>\u003cp>讨论时间结束，我们请學習者代表跟大家分享一下你们讨论的结果\u003cstrong>原因\u003c/strong>。\u003c/p>\u003cp>【小伙伴分享】\u003c/p>\u003cp>学习者代表：我们讨论出的\u003cstrong>原因\u003c/strong>有以下二个：\u003c/p>\u003cp>（1）知识经验有限,就是不知道\u003c/p>\u003cp>（2）技能能力有限,就是知道但做不到\u003c/p>\u003cp>【反馈和回应】\u003c/p>\u003cp>谢谢大家！现在我来总结一下大家的意见，讨论的结果一是，认为&quot;知识经验有限＂和＂技能能力有限&quot;这二种原因，造成＂做出来＂困难的原因，对不对?\u003c/p>\u003cp>学习者：对\u003c/p>\u003cp>统整的本质是一样的，二位再请想一下，认为这二个原因要能解决无效担忧＂做出来＂困难，最本质的原因，是什麽？请二位再讨论一下，等下来分享\u003c/p>\u003cp>学习者代表：經討論後，认为本质的原因有&quot;知识经验有限＂和＂技能能力有限&quot;造成＂做出来＂困难。\u003c/p>\u003cp>非常好，看来经过热烈讨论，在认知上,还有一些分歧，这二个原因当然都有关连，若真要选一个，让我们来小小玩个猜拳游戏，赢的人来说出最本质的原因，看来是&quot;知识经验有限＂为本质原因，造成＂做出来＂困难。请问小云学习者，也同意以&quot;知识经验有限＂为本质原因，继续探究下去，对吗?\u003c/p>\u003cp>学习者：对的\u003c/p>\u003cp>好的，那么我们找到了＂做出来＂感到困难的本质原因是：&quot;知识经验有限＂\u003c/p>\u003ch4>【4.引导分组讨论解决方案】\u003c/h4>\u003cp>现在我们已经清楚了＂做出来＂感到困难这个问题的本质是&quot;知识经验有限＂不足，那么接下来，我们就一起探讨一下怎么来解决这个问题。大家讨论之后要得到一份相对具体可操作的解决方案？给大家讨论5分钟，并把解决方案的要点记下来，讨论结束后请學習者代表來分享讨论的结果。\u003c/p>\u003cp>【学习者讨论】\u003c/p>\u003cp>小小:多拆书丶多请教人,请益之后更加有感悟丶多分享,接触到的事物会比较多,也会获得一些回馈\u003c/p>\u003cp>carol：针对不知道的部份，多上课学习；多请教专家和善用线上工具丶电子书等；多分享，分享是最好的学习，内化后，分享出去，就会为化为我们的知识和经验。\u003c/p>\u003cp>小小:我们有类似的地方：人丶事丶分享。\u003c/p>\u003cp>carol：对\u003c/p>\u003cp>拆书家：看到大家讨论很多解决方案，这裡提醒引导大家一下，要记得是具体可操作的解决方式，比如，何时参加拆书帮?一年要分享几次等的具体可操作方案哦！可以在讨论一下\u003c/p>\u003cp>小小:一个月做一个主题的拆书和广泛阅读，在拆书帮和脸书分享\u003c/p>\u003cp>carol：参加学习成长营丶讲师协会，扩展交际圈，与前辈们学习，这些单位都有固定输出的机会，如专题丶报导等，设定二个月或一个月一期的方式来输出。\u003c/p>\u003cp>拆书帮也是一个拆为己用的方式或组一个读书会，针对一个主题来探讨。\u003c/p>\u003ch4>【5.请每组派代表讲解自己组的成果】\u003c/h4>\u003cp>时间到，请学习者代表来分享大家讨论的解决方案。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>讨论的解决办法是：\u003c/p>\u003cp>1.脸书FB一月发一次文\u003c/p>\u003cp>2.每一期分享一次主题探讨\u003c/p>\u003cp>3.在学习成长营或讲师协会,做一季一期的专题分享\u003c/p>\u003cp>4.拆书帮的每月学习\u003c/p>\u003cp>【拆书家反馈】\u003c/p>\u003cp>从小伙伴们讨论的解决方案中，有没有觉得经过讨论出来的方案，对无效担忧＂做出来＂较困难，能够达成呢?\u003c/p>\u003cp>学习者：有。\u003c/p>\u003cp>大家觉得脸书FB一月发一次文丶在学习成长营或讲师协会,做一季一期的专题分享丶拆书帮的每月学习，方案的可行性大吗？\u003c/p>\u003cp>学习者：大。\u003c/p>\u003cp>拆书家：好的，祝贺大家找到可行的方法。让无效担忧能够化解，成为自我的三来医师。经验是从我们的学习丶分享丶行动中累积出来的，能力在这些过程中，也能渐长，能力提升后，当面对众多困难，也能看淡所发生的事情。\u003c/p>\u003cp>\u003cstrong>【A2】佈置任務\u003c/strong>\u003c/p>\u003cp>为了让大家能够学以致用,，请大家在未来三天左右,当你感到担忧时,试著用今天学到的三来方法,记下来丶分类来丶做出来,来面对担忧情境。我会在三天后，私讯问大家的学习感受。完成此小任务的人,会有小礼物赠送哦\u003c/p>\u003cp>【学习者作業】\u003c/p>\u003ch1>\u003cstrong>【強而有力的結束語】\u003c/strong>\u003c/h1>\u003cp>今天我们学到了拆页一建立自信的三方法:转记励，转记励是什麽？\u003c/p>\u003cp>学习者：转变态度丶记录要点丶自我激励\u003c/p>\u003cp>是的，想法会使一个人的人生发生转变。\u003c/p>\u003cp>拆页二面对担忧的三来方法，那三来?\u003c/p>\u003cp>学习者：记下来丶分类来丶做出来\u003c/p>\u003cp>是的，用三来医师方法，解决无效担忧\u003c/p>\u003cp>希望大家都能用此方法，在没自信时或者担忧时，能为你带来助力，有力量面心境，进而减少负面情绪和担忧的因素，顺利面对困难。\u003c/p>\u003cp>我的分享到此结束，感谢大家的陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1661263706000,"updated_at":1663164232000,"ria":true},{"id":13827,"topic":"将无效的担忧转化为有效的面对方案","learn_goal":"","remark":"在跟随我完成RIA现场学习后，学习者能够将无效的担忧转化为有效的面对方案。","level":"TF3-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"ivywang","city":""},"club":{"name":"台北悦读不卡分舵","city":"台北"},"prologue":"\u003cp>大家好，我是IVY，来自台湾台北的王靖蕙。现为二级拆书家。我的三个标签：劲量电池丶开创行者丶可视化卡片达人,欢迎参加我的TF3-2练级场。现在分组一下,就依现场的人数，自成一组。\u003c/p>\u003ch1>\u003cstrong>【图书介绍】\u003c/strong>场景介绍法\u003c/h1>\u003cp>（事件）（给出贴近学习者的生活经验，有画面）\u003c/p>\u003cp>大家有没有发现,今年的四丶五月,很像秋冬的天气,同时加上梅雨季节,夏天的衣服,似乎还派不上用场,而且湿答答的雨天,诸多的不便,出门要带雨具丶走路要小心,一不小心就会滑倒,在捷运上或公车上,脚还会被他人的雨伞触碰,深感难受。\u003c/p>\u003cp>（提问）(提问以引发学习者的思考，有思考）\u003c/p>\u003cp>问：这样的天气，你心情会不会也随之产生影响，变得闷闷地呢？\u003c/p>\u003cp>\u003cstrong>学习者回答?嗯!!心情会闷闷的,会讨厌这样的气侯\u003c/strong>\u003c/p>\u003cp>问：这样的心情会带给你什么样的影响呢？\u003c/p>\u003cp>\u003cstrong>学习者回答:會的,有股莫明的恐慌丶烦躁,同时还会连带引发不好的念头,有时还会自己吓自己\u003c/strong>\u003c/p>\u003cp>问：带来这些影响会导致那些事情随之发生变化呢？\u003c/p>\u003cp>学习者回答:会耶!有时主管的要求丶小孩的无理吵闹丶家人得了新冠肺炎，都會於大心態看待\u003c/p>\u003cp>（影响）(举出糟糕的后果，有痛点）\u003c/p>\u003cp>我们的心情，有时受天气的影响、有时受职场丶工作丶家人丶人际互动等情境，以及近期严峻的新冠肺炎而影响，如果我们没有好好处理担忧或者负面的情绪，将会影响身体健康，心病无药医的情况；或者太过杞人忧天，倒置胡思乱想，把时间都花费在担忧上，影响工作表现或升迁的机会；或者在人际互动上,动不动就心生忧鬱,别人都在说壞话,过度对号入座,导致心情太像玻璃心,一下就碎,太易受伤,因此看清情绪的变化和担忧,对我们无比的重要,如此才能身心健康。\u003c/p>\u003cp>（解决）(本书提出的方法能解决以上痛点，有方法）\u003c/p>\u003cp>自信力：成为最好的自己（第3版）一书，藉由许多的案例和方法的实际操作，让人重拾穫自信，进而拥有自信大，这个拆页,让我们透过自我察觉，解决无效的担忧和忧心，帮助我们有效面对自己的思绪过多，进而找到解方，勇于面对。\u003c/p>\u003cp>(学习目标)\u003c/p>\u003cp>在跟随我完成RIA现场学习后，学习者能够运用三来,记下来丶分类来丶做出来，能够将无效的担忧转化为有效的面对方案。\u003c/p>\u003ch1>【A1：量表自测】\u003c/h1>\u003cp>为了让大家更好地了解自己的担忧程度，下面请先来完成几道自测题，按照1-5的标准给自己打分，1分代表完全不符合，5分代表完全符合，请用1分钟的时间完成，并完成分数统计。做好的小伙伴示意一下。\u003c/p>\u003cp>总分： \u003c/p>\u003cp>【I-解释量表】\u003c/p>\u003cp>请各位对照一下自己的得分。\u003c/p>\u003cp>得分在10分以下，代表你的内心很平静，在此次学完拆页后,能有更好的表现哦;\u003c/p>\u003cp>得分在11-20分，要稍稍注意一下,自己的担忧,找到方法好好面对它。\u003c/p>\u003cp>得分在21分以上，你真的来对了,今天的学习,会对你很有帮助哦。\u003c/p>\u003cp>在此声明一下\u003c/p>\u003cp>自测题不是用来放大负面情绪或者否定自我，而是用来帮助大家清楚看到内心状态,进而面对问题,获得心情平静。\u003c/p>","ratings_count":1,"texts":[{"id":17850,"quote":"\u003cp>接下来我们花一分钟的时间,来看本次的拆页内容，來自《自信力：成为最好的自己（第3版）》微信電子書 P123\u003c/p>\u003cp>你有没有想过究竟什么是担忧？心理学家认为担忧是对未来可能出现的差错的一种无效的忧虑，令你担忧的事情可能包括被拒绝、失败、染上疾病或者遭遇车祸等。你会坐立不安，不停地思考“如果发生了这种事该怎么办？”“如果出了问题该怎么办？”然后你会想：“我无法应对这些事情！”\u003c/p>\u003cp>过度担忧的人不愿意停止担忧，因为他们（无意识地）相信考虑最坏的情况有助于他们做好准备。然而，心理学家发现在大多数情况下，我们的担忧实际上不能帮助我们有效地解决问题或者为未来做好准备。\u003c/p>\u003cp>大多数过度担忧的人没有思考过他们在担忧的时候做了什么。他们可能将自己的担忧视为“深谋远虑”或者“未雨绸缪”。因此为了减轻你的担忧，你要做的第一步就是记录你的担忧。在接下来的四个星期里，你要随身携带便签本，随时随地记录下你的担忧。\u003c/p>\u003cp>如何确定自己是否正在产生担忧？下面是关于担忧的常见信号。\u003c/p>\u003cp>·一遍又一遍地思考“如果发生了……”或者“噢，怎么会这样”之类的问题。\u003c/p>\u003cp>·思考不在你的能力控制范围之内的事情。\u003c/p>\u003cp>·关注最糟糕的事情，但实际上没有证据表明这些事情可能会发生。\u003c/p>\u003cp>每次你担忧某事时，就记录下当时的日期和时间，你担忧什么，以及你的担忧持续了多久。\u003c/p>","explains":"\u003ch1>【简短提问互动】\u003c/h1>\u003cp>【拆书家】大家看完这个拆页后,有人愿意分享一下是什麽内容?\u003c/p>\u003cp>【学习者】讲述担忧实际上不能帮助我们有效地解决问题或为未来做好准备。\u003c/p>\u003cp>【拆书家】拆页中,提到遇到担心时,会不停的想那三句话？\u003c/p>\u003cp>【学习者】\u003c/p>\u003cp>“如果发生了这种事该怎么办？”\u003c/p>\u003cp>“如果出了问题该怎么办？”\u003c/p>\u003cp>&quot;我无法应对这些事情！”\u003c/p>\u003cp>【拆书家】太好了,大家对拆页的内容都掌握的非常好!\u003c/p>\u003ch2>\u003cstrong>【What】\u003c/strong>\u003c/h2>\u003cp>担忧是一种心理因素,人会做出一些心理尝试以防止受到潜在的威胁,任何人不免都有此心理存在。\u003c/p>\u003ch2>\u003cstrong>【Ｗhy】\u003c/strong>\u003c/h2>\u003cp>为什麽我们要面对担忧丶了解担忧呢?常担忧的人, 容易吃不好、睡不好丶爱发呆丶爱生气,无法享受真正的生活;担忧太过会使我们对未来不抱希望,严重还会致癌。为了有一个美好人生,我们要正视我们的心理因素,找到面对的办法。\u003c/p>\u003ch2>\u003cstrong>【How具體步驟】\u003c/strong>\u003c/h2>\u003cp> 如何做?三来,记下来丶分类来丶做出来\u003c/p>\u003cp>1.记：简单记下来\u003c/p>\u003cp>把所担忧的事，简单寫下关键字来,让心中的烦恼丝能够抽丝剥茧\u003c/p>\u003cp>2.类：分出三类来\u003c/p>\u003cp>在所烦恼的众多烦恼丝，分出你觉得的三类程度来\u003c/p>\u003cp>最在乎：感到最担心的情绪\u003c/p>\u003cp>尚可以：介于在乎和不在乎之间\u003c/p>\u003cp>在乎低：觉这件事有转机，也没有自己想像中的担忧\u003c/p>\u003cp>3.做：尽力做出来\u003c/p>\u003cp>对最糟糕的事，尽力想出解决方案，最好多想几个，最少三个，找一个最简单又易行的去做。\u003c/p>\u003ch2>\u003cstrong>【舉例】\u003c/strong>\u003c/h2>\u003cp>案主：IVY\u003c/p>\u003cp>事件：上台演讲\u003c/p>\u003cp>时间：上週日\u003c/p>\u003cp>地点：课堂上\u003c/p>\u003cp>对象：台下的众多老师们\u003c/p>\u003cp>背景：\u003c/p>\u003cp>上周日因要上台分享，知道讲台下坐的都是大佬，心情莫名担忧怕自己表现不好，美食当前也吃不下，熬夜又早起，像极了洩了气的汽球；心情很容易感伤，虽出大太阳，感觉是下雨了。\u003c/p>\u003cp>于是我用了三来的方法，梳理自己心中的担忧。\u003c/p>\u003ch2>\u003cstrong>【预防异议】\u003c/strong>\u003c/h2>\u003cp>也许有人会觉得,这个三来方法看起来,有跟没有,没什麽差别!!若你这样想,可能就失去了一个可以观照自己的好机会;相信当人一担忧时,头脑是无法思考的,过度还会紧张无措,不知怎麽办。有一个好方法,让我们面对担忧,可说是,当自己的心理医师了。\u003c/p>\u003ch2>\u003cstrong>【适用边界】\u003c/strong>\u003c/h2>\u003cp>适用在当你感到担忧时或常动不动就担忧的人身上,若本身很开心,就不适宜用此方法。\u003c/p>","interaction":"\u003ch1>【A3】角色扮演\u003c/h1>\u003cp>現在我們來做個角色扮演的練習，場景是這樣的\u003c/p>\u003ch4>具体场景\u003c/h4>\u003cp>大美本身是一位敏锐又善感的人，在一家公司任职活动执行长，活动每次都办得普普通通，没什麽亮点；今年她的老闆，希望在一年一度的年终尾牙，办一场与往年不同的盛宴，展现公司活力的一面。\u003c/p>\u003cp>希望她能在八月时，先出份简单的企划书给他；大美心想，我手头正有一场展览，在七月底前完成筹备和佈置；老闆要我在八月赶出来，简直不可能。再者老闆交待完一声就出国去了，大美根本无法与老闆遇到面，同他争取缓衝。致使大美天天都睡不好。\u003c/p>\u003ch4>角色扮演\u003c/h4>\u003cp>我们现在来模拟一下大美的老闆丶大美本人丶以及充当大美的三来心理医师，二组刚好各二人,那IVY就充当老闆,谁要当大美?大美的心理医师。好，大家都超踊跃的。\u003c/p>\u003cp>请大家做小组练习,时间5分钟，可将讨论过程写在如下表格内,稍后邀请一组来演练分享\u003c/p>\u003cp>学习者扮演分享：\u003c/p>\u003cp>这个目的就是帮助我们釐清担忧的因素,透过三来的方法:记下来丶分类来丶做出来,清楚看到简单易执行的方法,能够减少担忧,顺利将事情完成,如同大家为大美找到好方法。\u003c/p>\u003ch1>【A2】布置任務\u003c/h1>\u003cp>为了让大家能够学以致用,，请大家在未来三天左右,当你感到担忧时,试著用今天学到的三来方法,记下来丶分类来丶做出来,来面对担忧情境。我会在三天后，私讯问大家的学习感受。完成此小任务的人,会有小礼物赠送哦\u003c/p>\u003cp>学习者分享：\u003c/p>\u003ch1>結語\u003c/h1>\u003cp>今天我们学到了面对担忧的三来方法，那三来?\u003c/p>\u003cp>学习者：记下来丶分类来丶做出来\u003c/p>\u003cp>是的，希望大家都能用此三来方法，在担忧时，能为你带来助力，有力量面对此心境，进而减少担忧的因素，顺利面对困难。我的分享到此结束，感谢大家的陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1658721496000,"updated_at":1659345815000,"ria":true},{"id":13705,"topic":"将无效的担忧转化为有效的面对方案","learn_goal":"","remark":"在跟随我完成RIA现场学习后，学习者能够将无效的担忧转化为有效的问题解决方案","level":"TF3-2","duration":25,"status":29,"type":0,"chaishujia":{"username":"ivywang","city":""},"club":{"name":"台北悦读不卡分舵","city":"台北"},"prologue":"\u003cp>大家好，我是IVY，来自台湾台北的王靖蕙。现为二级拆书家。我的三个标签：劲量电池丶开创行者丶可视化卡片达人,欢迎参加我的TF3-2练级场。现在分组一下,就依现场的人数，自成一组。\u003c/p>\u003ch1>\u003cstrong>【图书介绍】\u003c/strong>场景介绍法\u003c/h1>\u003cp>（事件）（给出贴近学习者的生活经验，有画面）\u003c/p>\u003cp>大家有没有发现,今年的四丶五月,很像秋冬的天气,同时加上梅雨季节,夏天的衣服,似乎还派不上用场,而且湿答答的雨天,诸多的不便,出门要带雨具丶走路要小心,一不小心就会滑倒,在捷运上或公车上,脚还会被他人的雨伞触碰,深感难受。\u003c/p>\u003cp>（提问）(提问以引发学习者的思考，有思考）\u003c/p>\u003cp>请问大家,这样的天气,你的心情是如何的呢?\u003c/p>\u003cp>有人愿意來简短分享一下?\u003c/p>\u003cp>学习者回答?心情会闷闷的,有股莫明的恐慌,有时还会自己吓自己\u003c/p>\u003cp>（影响）(举出糟糕的后果，有痛点）\u003c/p>\u003cp>有些人的心情往往会因为天气、某个情境或者他人眼神，而导致心情不好丶过度对号入座或担忧，从而影响健康丶人际丶财务丶家庭丶小孩丶工作丶升迁等事,使整个人沉闷,无法看清事实。\u003c/p>\u003cp>（解决）(本书提出的方法能解决以上痛点，有方法）\u003c/p>\u003cp>自信力：成为最好的自己（第3版）一书，藉由许多的案例和方法的实际操作，让人重拾穫自信，进而拥有自信大，这个拆页,让我们透过自我察觉，解决无效的担忧和忧心，帮助我们有效面对自己的思绪过多，进而找到解方，勇于面对。\u003c/p>\u003cp>(学习目标)\u003c/p>\u003cp>在跟随我完成RIA现场学习后，学习者能够运用三来,记下来丶分类来丶做出来，能够将无效的担忧转化为有效的面对方案。\u003c/p>\u003cp>【A1】环节,请大家进行量表自测,1分钟\u003c/p>\u003ch1>量表自测\u003c/h1>\u003ch1>【A1：量表自测】\u003c/h1>\u003cp>为了让大家更好地了解自己的担忧程度，下面请先来完成几道自测题，按照1-5的标准给自己打分，1分代表完全不符合，5分代表完全符合，请用1分钟的时间完成，并完成分数统计。做好的小伙伴示意一下。\u003c/p>\u003cp>【I-解释量表】\u003c/p>\u003cp>请各位对照一下自己的得分。\u003c/p>\u003cp>得分在10分以下，代表你的内心很平静，在此次学完拆页后,能有更好的表现哦;\u003c/p>\u003cp>得分在11-20分，要稍稍注意一下,自己的担忧,找到方法好好面对它。\u003c/p>\u003cp>得分在21分以上，你真的来对了,今天的学习,会对你很有帮助哦。\u003c/p>\u003cp>在此声明一下\u003c/p>\u003cp>自测题不是用来放大负面情绪或者否定自我，而是用来帮助大家清楚看到内心状态,进而面对问题,获得心情平静。\u003c/p>","ratings_count":3,"texts":[{"id":17731,"quote":"\u003ch1>R(不含HOW步驟流程)\u003c/h1>\u003cp>接下来我们花一分钟的时间,来看本次的拆页内容，來自《自信力：成为最好的自己（第3版）》微信電子書 P123\u003c/p>\u003cp>你有没有想过究竟什么是担忧？心理学家认为担忧是对未来可能出现的差错的一种无效的忧虑，令你担忧的事情可能包括被拒绝、失败、染上疾病或者遭遇车祸等。你会坐立不安，不停地思考“如果发生了这种事该怎么办？”“如果出了问题该怎么办？”然后你会想：“我无法应对这些事情！”\u003c/p>\u003cp>过度担忧的人不愿意停止担忧，因为他们（无意识地）相信考虑最坏的情况有助于他们做好准备。然而，心理学家发现在大多数情况下，我们的担忧实际上不能帮助我们有效地解决问题或者为未来做好准备。\u003c/p>","explains":"\u003ch1>【简短提问互动】\u003c/h1>\u003cp> 【拆书家】大家看完这个拆页后,有人愿意分享一下是什麽内容?\u003cbr>\u003c/p>\u003cp>【学习者】讲述担忧实际上不能帮助我们有效地解决问题或为未来做好准备。\u003cbr>\u003c/p>\u003cp>【拆书家】拆页中,提到遇到担心时,会不停的想那三句话？\u003cbr>\u003c/p>\u003cp>【学习者】\u003c/p>\u003cp>“如果发生了这种事该怎么办？”\u003c/p>\u003cp>“如果出了问题该怎么办？”\u003c/p>\u003cp>&quot;我无法应对这些事情！”\u003cbr>\u003c/p>\u003cp>【拆书家】太好了,大家对拆页的内容都掌握的非常好!\u003c/p>\u003ch2>\u003cstrong>【What】\u003c/strong>\u003c/h2>\u003cp>担忧是一种心理因素,人会做出一些心理尝试以防止受到潜在的威胁,任何人不免都有此心理存在。\u003c/p>\u003ch2>\u003cstrong>【Ｗhy】\u003c/strong>\u003c/h2>\u003cp>为什麽我们要面对担忧丶了解担忧呢?常担忧的人, 容易吃不好、睡不好丶爱发呆丶爱生气,无法享受真正的生活;担忧太过会使我们对未来不抱希望,严重还会致癌。为了有一个美好人生,我们要正视我们的心理因素,找到面对的办法。\u003c/p>\u003ch2>\u003cstrong>【How具體步驟】\u003c/strong>\u003c/h2>\u003cp> 如何做?三来,记下来丶分类来丶做出来\u003c/p>\u003cp>1.记：简单记下来\u003c/p>\u003cp>把所担忧的事，简单寫下关键字来,让心中的烦恼丝能够抽丝剥茧\u003c/p>\u003cp>2.类：分出三类来\u003c/p>\u003cp>在所烦恼的众多烦恼丝，分出你觉得的三类程度来\u003c/p>\u003cp>最在乎：感到最担心的情绪\u003c/p>\u003cp>尚可以：介于在乎和不在乎之间\u003c/p>\u003cp>在乎低：觉这件事有转机，也没有自己想像中的担忧\u003c/p>\u003cp>3.做：尽力做出来\u003c/p>\u003cp>对最糟糕的事，尽力想出解决方案，最好多想几个，最少三个，找一个最简单又易行的去做。\u003c/p>\u003ch2>\u003cstrong>【舉例】\u003c/strong>\u003c/h2>\u003cp>案主：IVY\u003c/p>\u003cp>事件：上台演讲\u003c/p>\u003cp>时间：上週日\u003c/p>\u003cp>地点：课堂上\u003c/p>\u003cp>对象：台下的众多老师们\u003c/p>\u003cp>背景：\u003c/p>\u003cp>上周日因要上台分享，知道讲台下坐的都是大佬，心情莫名担忧怕自己表现不好，美食当前也吃不下，熬夜又早起，像极了洩了气的汽球；心情很容易感伤，虽出大太阳，感觉是下雨了。\u003c/p>\u003cp>于是我用了三来的方法，梳理自己心中的担忧。\u003c/p>\u003ch2>\u003cstrong>【预防异议】\u003c/strong>\u003c/h2>\u003cp>也许有人会觉得,这个三来方法看起来,有跟没有,没什麽差别!!若你这样想,可能就失去了一个可以观照自己的好机会;相信当人一担忧时,头脑是无法思考的,过度还会紧张无措,不知怎麽办。有一个好方法,让我们面对担忧,可说是,当自己的心理医师了。\u003c/p>\u003ch2>\u003cstrong>【适用边界】\u003c/strong>\u003c/h2>\u003cp>适用在当你感到担忧时或常动不动就担忧的人身上,若本身很开心,就不适宜用此方法。\u003c/p>","interaction":"\u003ch1>【A3】角色扮演\u003c/h1>\u003ch4>具体场景\u003c/h4>\u003cp>大美本身是一位敏锐又善感的人，在一家公司任职活动执行长，活动每次都办得普普通通，没什麽亮点；今年她的老闆，希望在一年一度的年终尾牙，办一场与往年不同的盛宴，展现公司活力的一面。\u003c/p>\u003cp>希望她能在七月时，先出份简单的企划书给他；大美心想，我手头正有一场展览，在六月底前完成筹备和佈置；老闆要我在七月赶出来，简直不可能。再者老闆交待完一声就出国去了，大美根本无法与老闆遇到面，同他争取缓衝。致使大美天天都睡不好。\u003c/p>\u003ch4>角色扮演\u003c/h4>\u003cp>我们现在来模拟一下大美的老闆丶大美本人丶以及充当大美的三来心理医师，谁要当大美?大美的老闆?大美的心理医师。好，大家都超踊跃的。\u003c/p>\u003cp>学习者扮演分享：\u003c/p>\u003ch1>【A2】布置任務\u003c/h1>\u003cp>为了让大家能够学以致用,，请大家在未来三天左右,当你感到担忧时,试著用今天学到的三来方法,记下来丶分类来丶做出来,来面对担忧情境。我会在三天后，私讯问大家的学习感受。完成此小任务的人,会有小礼物赠送哦\u003c/p>\u003cp>学习者分享：\u003cbr>\u003c/p>\u003cp>事件：课程议义制作\u003c/p>\u003cp>经过：\u003c/p>\u003cp>这周未前需要把\u003cu>关键就业力课程讲义\u003c/u>完成并上传主办单位，由于准备的时间只有一周而且上传后就不能再修改，下次的考试必需按照讲义内容去演示。\u003c/p>\u003cp>仓促之间深怕准备不及又担心内容不够完善，因此，陷入一个既担心又害怕的情绪，每天早起又熬夜的赶PPT不说，自己的心理压力很大脾气也变不好了，连带周围的朋友也被影响了，整个人极为烦燥。\u003c/p>\u003cp>于是我用了三来的方法，梳理自己心中的不安的情绪。\u003c/p>\u003cp>我用了先求有再求完美的心态,在时间修改并完善了PPT,同时演练了数十次后,再上台,当天结果,顺利完成报告。很开心有这个好方法,帮助自己克服心中的担忧,顺利完成任务。\u003c/p>\u003ch1>結語\u003c/h1>\u003cp>今天我们学到了面对担忧的三来方法，那三来?\u003c/p>\u003cp>学习者：记下来丶分类来丶做出来\u003c/p>\u003cp>是的，希望大家都能用此三来方法，在担忧时，能为你带来助力，有力量面对此心境，进而减少担忧的因素，顺利面对困难。我的分享到此结束，感谢大家的陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1656857337000,"updated_at":1658404961000,"ria":true},{"id":13225,"topic":"主动采取行动，为自己人生带来改变。","learn_goal":"","remark":"在工作职场上，透过拆页主动做出改变的三行动：想改变的心丶终身来学习丶勇于去尝试，并列出三行动的具体场景和行动步骤，从而可视化建立主动出击的自信心。","level":"TF3-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"ivywang","city":""},"club":{"name":"台北悦读不卡分舵","city":"台北"},"prologue":"\u003cp>大家好，我是IVY，来自台湾台北的王靖蕙。现为二级拆书家。我的三个标签：劲量电池丶开创行者丶可视化卡片达人,欢迎参加我的TF3-1练级场。现在分组一下,就依现场的人数，自成一组。\u003c/p>\u003ch1>场景介绍法\u003c/h1>\u003cp>\u003cstrong>（事件）\u003c/strong>\u003c/p>\u003cp>大美在公司任职已有20年的时间,她把大把的青春都投入到公司,从来不迟到早退,也很少请假,做事效率效率平平,除此之外,大美平时也没有什么兴趣爱好,\u003cstrong>不会去做一些其他的娱乐和上课\u003c/strong>，做事效率平平，表现出来的样貌也是生惧害羞。\u003cstrong>期待被看到和升职加薪\u003c/strong>，但老闆似乎觉得她沒有符合资格的能力。\u003c/p>\u003cp>\u003cstrong>（提问）\u003c/strong>\u003c/p>\u003cp>在各位职场中,做事慢又生惧害羞,却想升职加薪的人,有吗?\u003c/p>\u003cp>大家觉得是什麽原因让她只想加薪?没有意识到老闆觉得她不符合加薪资格呢?\u003c/p>\u003cp>（学习者回答)\u003c/p>\u003cp>1.各位职场中,做事慢又生惧害羞,却想升职加薪的人,有吗?有的\u003c/p>\u003cp>2.大美有意识到老闆觉得她不符合加薪资格呢?大美似乎没有察觉\u003c/p>\u003cp>\u003cstrong>（影响）\u003c/strong>\u003c/p>\u003cp>是的，像大美资历不出色,却想被老闆丶主管看见，升职加薪，同时没有意识到自己的问题存在,就算她换了工作,也是一样的结果。\u003c/p>\u003cp>\u003cstrong>（解决）\u003c/strong>\u003c/p>\u003cp>自信力：成为最好的自己一书中的＂主动出击是你唯一的出路＂就是告诉我们想跳脱不被看见的没自信感，从今天的拆页中的三个行动：改变自己丶终身学习丶勇于尝试，让我们透过行动改变，成为被看见，有自信的人，不再生惧害羞。全书就如同书名一样,让我们可以透过种种技巧,成为最好的自己,充满自信力。\u003c/p>\u003cp>\u003cstrong>(学习目标)\u003c/strong>\u003c/p>\u003cp>在跟随我完成RIA现场学习后，学习者能够在工作职场上，透过拆页主动做出改变的三行动：想改变的心丶终身來学习丶勇于去尝试，并列出三行动的具体场景和行动步骤，从而可视化建立主动出击的自信心。\u003c/p>","ratings_count":2,"texts":[{"id":17216,"quote":"\u003cp>接下来我们花一分钟的时间,来看本次的拆页内容:自信力\u003c/p>\u003cp>《自信力》電子書P50-51\u003c/p>\u003cp>自信力意味着采取行动并勇于掌控，理解这一点至关重要。许多想变得更自信的人都希望自己的生活能焕然一新：他们希望老板更提携自己，配偶更体贴入微，自己有更多的时间和金钱，所做的一切也能与过去不同，并拥有更多、更好的机会。但是，除非有法力无边的魔鬼或者仙女能够随叫随到，否则一味地希望并不是个好办法。你的老板不会毫无缘由地主动来帮助你。你要么在老板的领导下工作，要么就去重新找一份老板更愿帮助员工的工作。如果你没有足够的时间和金钱（这年头谁不是这样呢？），你就需要主动挤出一点时间，额外存一点钱。你不主动做出改变，事情就不会改变。\u003c/p>","explains":"\u003cp>\u003cstrong>【Ｗhy】\u003c/strong>\u003c/p>\u003cp>为什么自信力很重要?一个人的展现,来自于他的行动,以及展现出来的样貌,生活和工作都一成不变,就会像死水一般,看不到生机;不做些改变，永远都是一位不被看见，同时与加薪升职无关连的人。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>自信的意思，在于本身自己愿意去做些什么？由行动改变中，获得从内而外的喜悦感，表现于外的信心笑容。其基础是用正面的态度肯定并接受自己的努力、成就与专长。\u003c/p>\u003cp>请大家看看以下几个案例是不是自信的表现：\u003c/p>\u003cp>1.如前面的事件中，大美在公司任职已有20年的时间,她把大把的青春都投入到公司,从来不迟到早退,也很少请假,做事效率平平,没有什麽兴趣爱好,也不会去做一些其他的娱乐和上课，表现出来的样貌很害羞胆怯。\u003c/p>\u003cp>大家觉得大美有没有意识到自己的问题所在?\u003c/p>\u003cp>学习者回答：没有。\u003c/p>\u003cp>大家回答的很正确，因为大美没有挤出时间去改变自己，学习口语表达或者胆量训练，增加被看见的机会。\u003c/p>\u003cp>2.再来举第二个案例，小白是位主管说东，不敢往西的人，整天只会拍主管的马屁，没什么专长的人，小白的老婆常说他，只会拍马屁，万一有一天你主管换口味了，你怎么办?\u003c/p>\u003cp>从小白的身上，大家有感受到拍马屁的行为吗?\u003c/p>\u003cp>学习者回答：有。\u003c/p>\u003cp>大家回答的很正确，小白因为认为拍马屁,是一种讨好主管的表现。不知拍马屁,并非代表个人的能力的提升,如果他把拍马屁的精力，用在改变自己身上，相信他一定是位能说能卖的好业务。\u003c/p>\u003cp>3.我们再来想想第三个案例，小强走踏常常低头看著地上，不抬头挺胸的人，大家觉得这算是一种自信的展现吗?\u003c/p>\u003cp>学习者回答：不太算。\u003c/p>\u003cp>大家回答的很正确，小强的行为状态，会使人感受到他似乎很消沉，对生活失去了信心。\u003c/p>\u003cp>根据原文片段自信力意味着采取行动并勇于掌控,做出一些改变,让生活变的不一样,个人也能从改变,获得信心,从而有自信心,这是一种对自我的肯定,小美丶小白丶小强的行为和表现,并没有意识到,要在行为上要改变，也没有给人从内而外的自信感。\u003c/p>\u003cp>\u003cstrong>【How具體步驟】\u003c/strong>\u003c/p>\u003cp>通过上面的例子,我提炼出增加自信心的三个步骤：\u003c/p>\u003cp>1.想改变的心\u003c/p>\u003cp>面对自己的目标，仔细思考，最想改变的是什麽？\u003c/p>\u003cp>如：大美想加薪，做出什麽改变,会令主管和老闆看见?\u003c/p>\u003cp>小白爱拍马屁,可以想想,获得主管赏识,还能增加些什麽?\u003c/p>\u003cp>2.终身來学习\u003c/p>\u003cp>将自己的薪水中的百分之10-20%提拨出来,做为投资自我的学习本钱。\u003c/p>\u003cp>如：大美做事效率平平和生惧害羞,可以去学行政效能的课程;或口语表达。\u003c/p>\u003cp>小白因没专长，把薪水中的百分之10-20%请老婆帮他提拨出来，去学另一个技能。\u003c/p>\u003cp>3.勇于去尝试\u003c/p>\u003cp>勇于尝试在说去试看看，什么新奇的事物，没有玩过或者什么好玩的地方，没有去过，主动跨出舒适圈，与人丶与事丶与大自然接触，都会是改变自己，使自己变得有自信的来源。\u003c/p>\u003cp>如：大美没有什么兴趣爱好，也不爱娱乐，可以去看看电影丶培养一个爱好，人精彩了，自然信心就来了。\u003c/p>\u003cp>小白可以多去与不同的人互动，从人的接触中，了解不是只有拍马屁这一途径，而是可以从本身的专长和自信，展现出来给主管肯定的。\u003c/p>\u003cp>【正例】\u003c/p>\u003cp>有自信的人，会有一颗愿意改变的心，如发现自己的阅读理解能力弱，会愿意找有改善的地方来终身学习，像大家愿意拆书过级，就是一种想改变和学习的心，在过程中，遇到不熟悉的技能点，都没有放弃，勇敢跨出舒适圈，来一关一关的过。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>也许你会想，大美和小白的情况，是他们的事，跟我无关，反正我工作稳定丶有父母可以靠，根本不需要做什么改变?但，没有永远的铁饭碗和永远可以陪伴我们一生的人，不是吗？因此我们更需要用改变自己丶终身学习丶勇于尝试，来为自己做些行动上的改变，让自己变的更有自信，迎刃一切的考验。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>这个方法适用在想改变自己的心态并提升自信力为主的人,若是沉睡之人,就不太适用此方法。\u003c/p>","interaction":"\u003cp>接下来，邀请大家来编一段增加自信心，主动改变的小故事，故事要交待你未來一周內可能会遇到或正在煩腦的情境，請包含背景、人物、情景变化（包括起因、经过、结果）以及有彼此对话内容的小剧本；剧本中的角色要体现“主动出击”的３个步骤：想改变的心、终身來习丶勇于去尝试，请用５分钟写下未来故事。\u003c/p>\u003cp>有疑问的人，请举个手让我知道。等会我们花二至三分钟来彼此分享。\u003c/p>\u003cp>好的，时间到，我们现在开始分享。时间是２—３分钟。我看大家都分享完了，\u003c/p>\u003cp>请问有哪一位小伙伴愿意同大家分享内容吗？\u003c/p>\u003cp>学习者：小小\u003c/p>\u003cp>掌声鼓励~感谢这位小伙伴跟我们分享这么生动精彩的主动出击安排自我提升理财能力，让人生充满精彩与自信。\u003c/p>\u003ch1>强而有力的总结\u003c/h1>\u003cp>世上什麽最公平,我想,就是老天爷给我们每一人都拥有24小时的时间,如果我们不为自己的人生做些改变,只想要天上掉下来的礼物,就算你有能力收下,可能也无福消受;自己的人生自己掌舵,花点时间丶存一点钱丶勇于尝试,为自己带来改变外,人生变精彩之外,同时也会是一位阳光自信的人。\u003c/p>\u003cp>希望大家把这个方法运用到生活和工作，成为主动出击带来成长的自信者。\u003c/p>\u003cp>我的分享到此结束，感谢大家的陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1648887033000,"updated_at":1650435345000,"ria":true},{"id":12874,"topic":"主动采取行动，为自己人生带来改变。","learn_goal":"","remark":"改变的三行动：擠出時間丶存一點錢丶勇於嘗試，并列出三行动的具体场景和行动步骤，从而可视化建立主动出击的自信心。","level":"TF3-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"ivywang","city":""},"club":{"name":"台北悦读不卡分舵","city":"台北"},"prologue":"\u003cp>大家好，我是IVY，来自台湾台北的王靖蕙。现为二级拆书家。我的三个标签：劲量电池丶开创行者丶可视化卡片达人,欢迎参加我的3-1练级场。现在分组一下,就依现场的人数，自成一组。\u003c/p>\u003ch1>场景介绍法\u003c/h1>\u003cp>\u003cstrong>（事件）\u003c/strong>\u003c/p>\u003cp>大美在公司任职已有20年的时间,她把大把的青春都投入到公司,从来不迟到早退,也很少请假,做事效率都是最快最优秀的那一位,除此之外,大美平时也没有什么兴趣爱好,\u003cstrong>不会去做一些其他的娱乐和上课\u003c/strong>，虽做事效率佳，但表现出来的样貌,却是生惧害羞。\u003cstrong>期待被看到和升职加薪\u003c/strong>，但老闆似乎觉得她沒有符合资格的能力。\u003c/p>\u003cp>\u003cstrong>（提问）\u003c/strong>\u003c/p>\u003cp>在我们的生活当中像大美这样的人有没有？什么原因造成他们不被看见和没有升职呢？\u003c/p>\u003cp>（学习者回答)\u003c/p>\u003cp>1.生活当中像大美这样的人有没有？有的\u003cbr>2.什么原因造成他们不被看见和没有升职呢?没自信丶畏畏缩缩\u003c/p>\u003cp>\u003cstrong>（影响）\u003c/strong>\u003c/p>\u003cp>是的，就像大美一样努力却没被老闆丶主管看见，同时也没被升职加薪，这会使人工作越来越消沉，人也会变得越来越没自信。因为不被认可而让自己更加没有了成就感，甚至失去人生前进的动力，得过且过；更甚者还会导致出现心理上的障碍等等。\u003c/p>\u003cp>\u003cstrong>（解决）\u003c/strong>\u003c/p>\u003cp>自信力：成为最好的自己一书中的＂主动出击是你唯一的出路＂就是告诉我们想跳脱不被看见的没自信感，从今天的拆页中的三个行动：挤出时间丶存一点钱丶勇于尝试，让我们透过改变，成为被看见，有自信的人，不再生惧害羞。全书就如同书名一样,让我们可以透过种种技巧,成为最好的自己,充满自信力。\u003c/p>\u003cp>\u003cstrong>(学习目标)\u003c/strong>\u003c/p>\u003cp>在跟随我完成RIA现场学习后，学习者能够在工作职场上，透过拆页主动做出改变的三行动：擠出時間丶存一點錢丶勇於嘗試，并列出三行动的具体场景和行动步骤，从而可视化建立主动出击的自信心。\u003c/p>","ratings_count":2,"texts":[{"id":16838,"quote":"\u003cp>接下来我们花一分钟的时间,来看本次的拆页内容:自信力\u003c/p>\u003cp>《自信力》電子書P50-51\u003c/p>\u003cp>自信力意味着采取行动并勇于掌控，理解这一点至关重要。许多想变得更自信的人都希望自己的生活能焕然一新：他们希望老板更提携自己，配偶更体贴入微，自己有更多的时间和金钱，所做的一切也能与过去不同，并拥有更多、更好的机会。但是，除非有法力无边的魔鬼或者仙女能够随叫随到，否则一味地希望并不是个好办法。你的老板不会毫无缘由地主动来帮助你。你要么在老板的领导下工作，要么就去重新找一份老板更愿帮助员工的工作。如果你没有足够的时间和金钱（这年头谁不是这样呢？），你就需要主动挤出一点时间，额外存一点钱。你不主动做出改变，事情就不会改变。\u003c/p>","explains":"\u003cp>\u003cstrong>【Ｗhy】\u003c/strong>\u003c/p>\u003cp>为什么自信力很重要?一个人的展现,来自于他的行动,以及展现出来的样貌,生活和工作都一成不变,就会像死水一般,看不到生机;不做些改变，永远都是一位不被看见，同时与加薪升职无关连的人。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>自信的意思，在于本身自己愿意去做些什么？由行动改变中，获得从内而外的喜悦感，表现于外的信心笑容。其基础是用正面的态度肯定并接受自己的努力、成就与专长。\u003c/p>\u003cp>请大家看看以下几个案例是不是自信的表现：\u003c/p>\u003cp>1.如前面的事件中，大美在公司任职已有20年的时间,她把大把的青春都投入到公司,从来不迟到早退,也很少请假,做事效率都是最快最优秀的那一位,除此之外,大美平时也没有什么兴趣爱好,不会去做一些其他的娱乐和上课，虽做事效率佳，但表现出来的样貌,却是生惧害羞。\u003c/p>\u003cp>大家觉得大美是一位有自信的人吗?\u003c/p>\u003cp>学习者回答：不是。\u003c/p>\u003cp>大家回答的很正确，因為大美沒有挤出时间学习，如果她能学习口语表达或者胆量训练，就能增加被看見的機會。\u003c/p>\u003cp>2.再来看第二个案例，小白是位主管说东，不敢往西的人，整天只会拍主管的马屁，没什麽专长的人，小白的老婆常说他，只会拍马屁，万一有一天你主管换口味了，你怎麽办?\u003c/p>\u003cp>从小白的身上，大家有感受到他有自信吗?\u003c/p>\u003cp>学习者回答：沒有。\u003c/p>\u003cp>大家回答的很正确，小白因为没有自信，才会爱拍马屁。如果他把拍马屁的精力，用在自我投资上，相信他一定是位能说能卖的好业务。\u003c/p>\u003cp>\u003cstrong>【How具體步驟】\u003c/strong>\u003c/p>\u003cp>通过上面的例子我提炼出增加自信心的三个步骤：\u003c/p>\u003cp>1.时：挤出时间\u003c/p>\u003cp>每天用１—２小时来学习，朝最想改善的地方入理。\u003c/p>\u003cp>如：大美因生惧害羞，下班后，可以去学习口语表达或者胆量训练。\u003c/p>\u003cp>小白因有拍马屁的特质，上班有空閒时，可以去请教同事的业务技巧或下班去进修。\u003c/p>\u003cp>2.钱：存一点钱\u003c/p>\u003cp>将自己的薪水中的百分之10-20%提拨出来,存下来,做为日后投资自我的本钱。\u003c/p>\u003cp>如：大美做了２０多年，没有功劳也有苦劳，年终或者福利应不赖，可以从中来提拨。\u003c/p>\u003cp>小白因没专长，更要把薪水中的百分之10-20%请老婆帮他存下来，做为日后可以去学一技之长的学费。\u003c/p>\u003cp>3.试：勇于尝试\u003c/p>\u003cp>勇于尝试在说去试看看，什么新奇的事物，没有玩过或者什么好玩的地方，没有去过，主动跨出舒适圈，与人丶与事丶与大自然接触，都会是改变自己，使自己变得有自信的来源。\u003c/p>\u003cp>如：大美没有什么兴趣爱好，也不爱娱乐，可以去看看电影丶培养一个爱好，人精彩了，自然信心就来了。\u003c/p>\u003cp>建议小白可以多去与不同的人互动，从人的接触中，了解不是只有拍马屁这一途径，而是可以从本身的专长和自信，展现出来给主管肯定的。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>也许你会想，大美和小白的情况，是他们的事，跟我无关，反正我工作稳定丶有父母可以靠，根本不需要做什么改变?但，没有永远的铁饭碗和永远可以陪伴我们一生的人，不是吗？因此我们更需要用&quot;时丶钱丶试&quot;来为自己做些改变，让自己变的更有自信，迎刃一切的考验。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>这个方法适用在想改变自己的心态上,若是沉睡之人,就不太适用此方法。\u003c/p>","interaction":"\u003ch1>Ａ２未来故事\u003c/h1>\u003cp>接下来，邀请大家来编一段小故事，有主题、人物、情景变化（包括起因、经过、结果）以及有彼此对话内容的小剧本；剧本中的角色要体现“主动出击”的３个步骤，请用５分钟写下未来故事。\u003c/p>\u003cp>有疑问的人，请举个手让我知道。\u003c/p>\u003cp>等会我们花二至三分钟来彼此分享。\u003c/p>\u003cp>好的，时间到，我们现在开始分享。时间是２—３分钟。我看大家都分享完了，\u003c/p>\u003cp>请问有哪一位小伙伴愿意同大家分享内容吗？\u003c/p>\u003cp>学习者：\u003c/p>\u003ch1>反馈\u003c/h1>\u003cp>掌声鼓励~感谢这位小伙伴跟我们分享这么生动精彩的主动出击安排期待建议同事提升行政文书能力,让人生充满精彩与自信。\u003c/p>\u003ch1>总结\u003c/h1>\u003cp>世上什麽最公平,我想,就是老天爷给我们每一人都拥有24小时的时间,如果我们不为自己的人生做些改变,只想要天上掉下来的礼物,就算你有能力收下,可能也无福消受;自己的人生自己掌舵,花点时间丶存一点钱丶勇于尝试,为自己带来改变外,人生变精彩之外,同时也会是一位阳光自信的人。\u003c/p>\u003cp>希望大家把这个方法运用到生活和工作，成为主动出击带来成长的自信者。\u003c/p>\u003cp>我的分享到此结束，感谢大家的陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1640752484000,"updated_at":1642869925000,"ria":true},{"id":12361,"topic":"从舒适圈跨出对生活和工作的自我反思并以自评方式找到人生想专注的三领域;当遇到挫折时,能够当人生的自我教练,来让自信心充满力量，面对一切困扰，实现未来不是梦。","learn_goal":"","remark":"在跟随我完成RIA现场学习后，学习者能够透过拆页一，在人生迷网时, 能运用自我评分的方法, 找到人生想专注的三个领域；并且透过拆页二，当面对人生困境或疑惑不定时，透过六步骤写下给自己的一封信中，从停滞不前，进而愿意行动。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"ivywang","city":""},"club":{"name":"台北悦读不卡分舵","city":"台北"},"prologue":"\u003cp>大家好，我是IVY，来自台湾台北的王靖蕙。我的三个标签：劲量电池丶开创行者丶值得信赖,欢迎参加我的2-4练级场，今天的学习有许多演练环节，现在分组一下,就依现场的人数，自成一组。\u003c/p>\u003ch2>\u003cstrong>【图书介绍】1分钟\u003c/strong>\u003c/h2>\u003cp>【F】今天我要给大家介绍的这本书《自信力：成为最好的自己》作者：英国-罗布.杨博士是顶尖的商业演讲家,心理学权威人士，本书分为二大部份，自信力成就最好的自己和生活处处是自信，是本帮助我们举手投足和在人生每个时刻都能拥有自信力的一本好书。透过这本书的现场拆书,将使你从容不迫,面对挫折和难解之题，找到最好的解决之道,向最好的自己迈进。\u003c/p>\u003cp>【A】与其他同类书籍相比，这本书裡面的自信力助进器非常简要又好实作，除了作者本身是心理学权威外，本书也提到许多案例，可说是有案例有方法，令人看过后，易执行且获得好自信的好方法。今日的二则拆页内容，皆来自这本书的自信力助进器，可谓是本实践类的好书。\u003c/p>\u003cp>【B1】这本书教你面对人生中种种的问题，运用自信力助进器的方法,从容不迫面对各种疑难杂症，找到最妥善的面对之道。此书里都有方法，让我们找到解决问题的答案，成為人生的主人翁。\u003c/p>\u003cp>【B2】今天这两个拆页讲的是，在舒适圈中，面对生活工作不再激情与活力，如何重燃人生干劲，立下人生专注三领域，落实执行；当面对挫折不顺时，如何透过自我教练六步骤，再度迎刃而解，成为自己的人生教练，做自己的人生设计师。\u003c/p>\u003cp>\u003cstrong>【拆页一学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成拆页一的RIA现场学习后，学习者能够：\u003c/p>\u003cp>在人生迷网以及失去热情时, 能运用自我评分的方法, 找到人生想专注的三个领域\u003c/p>","ratings_count":2,"texts":[{"id":16294,"quote":"\u003ch2>\u003cstrong>【R阅读拆页一】2分钟\u003c/strong>\u003c/h2>\u003cp>來源：《自信力.成为最好的自己》（第3版）微信电子书 你的未來就是夢 P263-264\u003c/p>\u003cp>27岁的卡特已经在网络游戏公司担任软件工程师多年。他拥有舒适的生活，但是他觉得自己的生活缺乏激情和挑战。\u003c/p>\u003cp>然而，现在他不再有这种感觉。虽然他兴趣广泛，但是他决定专注于三个特别的领域，在这些领域中他对自己的表现不太满意。他写出了自己的初步目标。\u003c/p>\u003cp>·我的健康状况：我的身体正在变得虚弱无力，我的同事杰西卡（Jessica）说我有了啤酒肚。我想通过健身和减肥，让自己的身体重获健康与活力。\u003c/p>\u003cp>·我的职业生涯：我想拓展我的工作范围，而不是日复一日去完成同样枯燥的任务。我喜欢我的工作，但我不能违心地说这份工作激发了我的热情和斗志。我想找一份新的工作，做一些新鲜的事情，并且沉浸其中。我甚至可以辞职创业。\u003c/p>\u003cp>·我的经济状况：我想在接下来的几年里买一套房子。对于现在来说这是不可能的，我没有足够的储蓄，只能租房住，所以我会找理财顾问谈谈，了解我可以借多少钱，制订一个理财计划。今年我可能还无法购买房子，但是我一定会在年底前制订理财计划。\u003c/p>","explains":"\u003cp>\u003cstrong>【I讲解】4分钟\u003cbr>\u003c/strong>\u003cbr>好，我看到大家已经看完拆页了，接下来我就分享一下我的理解和体会。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>舒适生活丶兴趣广泛丶工作繁複，一成不变，大约是现今的普遍现象，这是一篇，要我们展望未来的一个实例，要我們不要固守现况，而要去构建想要实现的目标，专注在三个领域上。如：健康丶职业丶经济状况。\u003c/p>\u003cp>【意译案例】根据原书中案例脉络，给出更贴近实际的例子。\u003c/p>\u003cp>40多岁的IVY已经在不动产公司担任会计一职多年。她拥有稳定又离家近的的生活，但是她觉得自己的人生中少了一些精彩和动力。\u003c/p>\u003cp>然而，现在她不再有这种感觉。虽然她什么都想学，学习热烈，但是她决定专注于三个专注的领域，在这些领域中，她对自己的表现不太满意。她写出了自己的初步目标。\u003c/p>\u003cp>我的人生意义：\u003c/p>\u003cp>我想用阅读图卡的方式,丰富我的人生记录,进而影响更多人,，让自己所做的图卡，使更多人受益。\u003c/p>\u003cp>我的健康状况：\u003c/p>\u003cp>我的运动跑步随著疫情的关係,以乎停摆中，以致这段时间养成了晚睡，眼睛也因睡眠不足，长了针眼；我应该开始养成规律的早睡早起习惯，于每天六点到七点启动晨间跑步的练习，让大汗淋漓使自己变得更开心和更有活力朝力。\u003c/p>\u003cp>我的职业生涯：\u003c/p>\u003cp>我想挑战我的会计工作，而不是天天都做著枯燥繁锁的任务。我喜欢我现在的这一份工作，但我不能睁眼说瞎话地说这份工作有给我丰收和成就。我想在现有的工作中，做一些挑战的事情，并且享受其中。我甚至可以将工作内容化为图解流程。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>为什么要用这样的方式检视自己来实现想要的生活如此重要呢?没有人会希望生活是一成不变的，都会期望精彩可期，人不可能一辈子都在固有模式下生活，因此要勇于去构建未来想过的生活。让这一生不致于空过一生，同时可以自信迎接。\u003c/p>\u003cp>【2-1强调不这么做的坏处（失败的经验）】\u003c/p>\u003cp>大部份的人，每天过的日子，上班丶下班丶煮饭丶洗衣丶骂小孩丶滑手机丶追剧，生活很枯燥，重心也都在工作和家人身上，以及自我鬆散上，固守现况，不乐意改变，终其一生，就是这样渡过，人生是一张白纸；现在若我们愿意突破现况，给自己一些时间如同案例中的卡特专注在特定的三个领域中，未来必会不遗憾此生，并聚焦在乐爱的愿景上。\u003c/p>\u003cp>【how】（细化步骤)\u003c/p>\u003cp>那要如何做呢?我将卡特的案例,依拆页的前后文,拆解为成三步，当我们还不知从何入理那些领域时,我们可以先来这样做？\u003c/p>\u003cp>1.自我评分\u003c/p>\u003cp>案例中的卡特有对现在的工作和生活满意度进行了思考；我们也可以如法泡製，首先想下自己现在的工作和生活满意度，并根据工作和生活满意度,在\u003c/p>\u003cp>八个领域表格中自我评分，１—１０分的满意分,1分最低,10分最高\u003c/p>\u003cp>2.检视反思\u003c/p>\u003cp>评分好了之后,分出高分和低分,低分代表自信力低,没有被满足的地方,也是你内心渴望完成的部份;高分代表目前为止,是自信做的还不错的地方。\u003c/p>\u003cp>3.落实方向\u003c/p>\u003cp>人生的精力有限，因此你要从自我评分表中，去选出三个领域，可以改变未来短期一年内，能够实现愿望的领域，你可以高低分搭配。也可以全低分丶全高分搭配，主要还是你自己想要过得更自信为主。\u003c/p>\u003cp>如同案例中，写出你的三领域的初步目标。\u003c/p>\u003cp>【一般做法】\u003c/p>\u003cp>一般人的人生，是没有目标和想专注的领域的，每天就是过日子，不知自己的人生能做什麽？\u003c/p>\u003cp>【列举反例】失败案例\u003c/p>\u003cp>像我学校毕业后，以为学到一技之长就够了，进入社会，上班下班，不思进取，浑浑噩噩渡过了好几十年的黑白人生，宅女阿肥是我的代表词。\u003c/p>\u003cp>【加工成正例】\u003c/p>\u003cp>直到有一次我去看了一场白日梦冒险王电影之后，我开始正视自己的人生，觉得自己跟电影中的男主角好像，因我们都是当会计；我用自我评分法的三个步骤,发现我的人生如同一张白纸，一点都不精彩，且如同一潭死水，因此我从评分表中，选出自己最想专注的部份，人生意义丶健康状况丶职业生涯，开始跨出学习丶开始在没有尝试过的领域前进，如爬山丶游泳丶跑步丶阅读书卡等领领域前进，我的人生变的不同了，我变瘦了丶我变的有气质了丶我变的有自信了，同时更对未来充满期许，原来我的潜力如此之大，自己都觉得不可思议。\u003c/p>\u003cp>【反思】\u003c/p>\u003cp>如果当时我没有藉由电影自我评分现况,我还是一样宅在家，没有走出去，我可能一辈子，就活在自己的井字天空。检视反思才能开拓,若没有落实执行,更无法站在这儿与大家分享了。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能有人会想，评分检示，我不想评耶！我的人生看来没有什麽问题！！！要我评，办不到。无法懂得自我评分的人生，是没有自信的代表，这是逃避而非面对,因为，每个人,这一生都会有想要去的地方丶想要完成的事丶或者想给人幸福的能力。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这个方法，很适合用在检视现况，以及想创造未来的方向上，当我们对生活缺乏激情丶索然无味和挑战时，可以用自我评分丶检视反思丶落实行动这方法，来使自己对未来有期待，让未来不是梦，得以实现。若对自己很有把握的情况时,就较不适会用此方法。\u003c/p>","interaction":"\u003ch2>【A1激活经验】\u003c/h2>\u003ch2>回忆一下，你最近半年，有没有遇到像拆页一人物卡特,对健康丶职涯丶经济状况充满不确定性的担忧，对未来没有期待。请大家先在组内分享，时间为１—２分钟，一会也请小伙伴分享一下。\u003c/h2>\u003cp>\u003cstrong>【学习者分享的案例1：小雲】\u003c/strong>\u003c/p>\u003cp>今年初在做新年新愿望时，回顾去年希望全家戒糖的计划和财务规划时，觉得自己空有决心，但执行力似乎不够。另外孩子即将进入国中开始烧钱求学阶段似乎要做更多准备才行。\u003c/p>\u003cp>\u003cstrong>【学习者分享的案例:carol】\u003c/strong>\u003c/p>\u003cp>工作和家庭都让自己身心有些疲惫,长期下来,感受到身体健康似乎有些失去平衡。\u003c/p>\u003cp>【A1+加工成正例】\u003c/p>\u003cp>如果时间再回溯，你会用今天学到的自我评分法三步骤来选择？\u003c/p>\u003cp>\u003cstrong>【学习者分享的案例】\u003c/strong>\u003c/p>\u003cp>1.自我评分：如上表格\u003c/p>\u003cp>2.检视反思：更加了解自我状态,要好好重新定位。\u003c/p>\u003cp>3.落实方向：健康状况丶人生意义丶业馀生活。\u003c/p>\u003cp>1.自我评分：如上表格\u003c/p>\u003cp>2.检视反思：在目前时间规划上比较少投入投资理财、亲密亲子关係、社交生活这三方面。\u003c/p>\u003cp>3.落实方向：亲密亲子关係、投资理财、人生意义\u003c/p>\u003cp>\u003cstrong>【关门过渡】\u003c/strong>\u003c/p>\u003cp>拆页一我们学习了，如何对现况自我评分？并且检视反思，同时落实执行，为自己构建未来的目标，相信大家的未来都不是梦 ,并能逐梦而踏实。而在过程中，我们不可能时时都会遇到贵人助我们一把，或者有人可以请益，因此我们接下来的拆页二学习，就是当我们对目标有坚持不下去时，可以用自我教练的方式，当自己的人生贵人。\u003c/p>\u003cp>下面我们就来学习拆页二。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":16295,"quote":"\u003cp>\u003cstrong>【拆页二学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成拆页二的RIA现场学习后，当面对人生困境或疑惑不定丶事情太多时，透过六步骤写下给自己的一封信中，从停滞不前，进而愿意行动。\u003c/p>\u003ch2>\u003cstrong>【R阅读拆页二】2分钟\u003c/strong>\u003c/h2>\u003cp>来源：自信力：成为最好的自己（第3版）微信电子书p407\u003c/p>\u003cp>自信力助推器：做自己的教练\u003c/p>\u003cp>想象你是你的一位好朋友，给你写了一封信，帮助你分析当前的情况，指出你有哪些选择，最后提出合适的解决问题的办法。在信的开头一定要写上“亲爱的XX（你自己的名字）”，然后按照下面的步骤来写。\u003c/p>\u003cp>1.明确当前的问题或困境。找一张干净的纸，然后在上面描述出当前的情况。不要担心不知道该写什么，只要动手写就可以了，比如“我看到你现在的情况是……”。也许你写了几句话之后，突然有了灵感，后面要写什么也就顺理成章地写出来了。在写的过程中，要记得描述发生了什么事情以及你有什么感受。\u003c/p>\u003cp>2.列举可能的选择。把所有可能解决当前困难的办法都写下来。即便是对那些非黑即白、非此即彼的问题，你也可以在极端的办法之间找到很多灵活变通的方法。比如说，当你和配偶的婚姻关系出现问题时，除了选择继续在一起或者永远地分开以外，还可以选择暂时分居或是接受婚姻咨询服务。如果暂时分居，还可以选择到朋友家去住上几个星期，也可以自己找房子住半年。只要稍微想一想，你就会有比最初多得多的想法。\u003c/p>\u003cp>3.权衡利弊。写下每一种办法的利与弊，以及这些办法给你的感受。通过权衡利弊，你能够很轻易地找出哪些办法最有建设性。\u003c/p>\u003cp>4.向前一小步。摆脱非此即彼的视角，重新审视你的现状，你可能就会发现自己应该前进的方向了。\u003c/p>\u003cp>很多人都在选择方向的时候无所适从，因为他们不知道哪种选择是对的。但是如果一直犹豫不决，这只会让你停滞不前。结果，看起来你好像还没有做出选择，但其实你已经选择了放弃。\u003c/p>\u003cp>行动本身就意味着进步。如果你不喜欢自己选择的事，至少你也知道了自己不喜欢什么。如果发现自己做了错误的决定，至少你也知道了正确答案不是这个。只要你做出决定，便会知道下一步该做些什么，不论是做什么，都比什么也不做要好。\u003c/p>\u003cp>在你的信中，有你对当前发生事情的描述，也有你对这些事情感受的描述，既有事实又有情感。这样做的原因是当你将自己的感受也考虑在内时，能够找到更有效的解决办法。曾经有研究者调查了一群被解雇的人，发现那些写下自己失业感受的人，比那些没有写过感受的人能更快地找到新工作。写感受并不是为了释放情绪而采用的空洞技术，它确实能够提供给人们更有效的解决办法。所以为了让自己更好地应对困境，记得不光要写事实，还要写感受。\u003c/p>","explains":"\u003cp>\u003cstrong>【I讲解】5分钟\u003c/strong>\u003c/p>\u003cp>好，我看到大家已经看完拆页了，接下来我就分享一下我的理解和体会。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>这是把自己当成自己的好朋友丶好教练,在面对困境时，用有效的解決步驟,來使你有自信心去迎接它，完成自己的愿望和目标，不受困难或挫败问题所影响而前置不前的好方法。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>为什么要学此方法?人生中，不可能一帆风顺，当遇到不如意或者挫折以及複杂的问题时，我们就能透过自我教练法，在人生的这些时刻中，做自己的主人。可说是成为自己贵人的好方法。\u003c/p>\u003cp>【How】\u003c/p>\u003cp>如何来写这封信呢？我们从前面拆页一想专注的三个领域来延伸，准备一张纸，开头写下：\u003c/p>\u003cp>亲爱的IVY：\u003c/p>\u003cp>看到你为自己设下专注在三个领域（人生意义丶健康状况丶职业生涯）上，如此弘大且实践路上的目标,很为你感到开心,同时相信,你会知道,接下来你要面对的困境和问题,会是什么?\u003c/p>\u003cp>（拆页中的第一步骤)\u003c/p>\u003cp>1.现况：描述当前情况（问题丶事实丶感受丶情感都可以写)\u003c/p>\u003cp>你说，工作太忙丶下班后要学习丶执行线上课以及制卡，已分身乏术，实在无法再学习＂写作&quot;新的领域。\u003c/p>\u003cp>（细化步骤拆页的第二步骤：列举可能的选择一分為三：排序丶提醒丶選擇)\u003c/p>\u003cp>2.排序：排列优先顺序\u003c/p>\u003cp>原拆页的第二步骤：列举可能的选择，为方便大家应用，我再细分为：排序丶提醒丶选择\u003c/p>\u003cp>我建议你，面对如此多的情况，先从八大面向自我评分一下，再来排列优先顺序(１—１０分，10分为满分)\u003c/p>\u003cp>从高至低排列\u003c/p>\u003cp>职业生涯\u003c/p>\u003cp>健康状况\u003c/p>\u003cp>人生意义\u003c/p>\u003cp>家庭生活\u003c/p>\u003cp>业馀生活\u003c/p>\u003cp>社交生活\u003c/p>\u003cp>投资理财\u003c/p>\u003cp>亲密关係\u003c/p>\u003cp>3提醒：写下自我提醒\u003c/p>\u003cp>看来你的分数和想专注的三领域上，一比较后，最弱的是人生意义，而非写作，是不是要想下，写作真的是你现在的当务之急吗?\u003c/p>\u003cp>4.选择：选择可行事项\u003c/p>\u003cp>请你静下心来，运用检视反思的回顾，在这八大面向中，你想做的是什么\u003c/p>\u003cp>？想好后，重新做选择\u003c/p>\u003cp>职业生涯\u003c/p>\u003cp>健康状况\u003c/p>\u003cp>人生意义\u003c/p>\u003cp>（拆页的第三步骤：权衡利弊)\u003c/p>\u003cp>5.分析：分析所选项目\u003c/p>\u003cp>职业生涯：职业在一天中佔领最多的时间，保好饭碗，衣食不愁。\u003c/p>\u003cp>健康状况：健康是本，疫情无法运动的时期，良好的睡眠和在家做伸展和深蹲\u003c/p>\u003cp>人生意义：有了安心的资粮和健康的身体，才能发挥自己想在阅读书卡上的影响。\u003c/p>\u003cp>（拆页的第四步骤：向前一小步)\u003c/p>\u003cp>6.执行:选出重要执行\u003c/p>\u003cp>当你明白了时间和精力，以及健康的重要，要有好脑力，请从现在起，每天睡足６—７小时，千万不要再熬夜，没有好体力，就没有好脑力，更无法把想做的任务完成哦。请以健康的基础下，完成另二个领域，健康是本，记得睡眠充足很重要，不可轻忽。\u003c/p>\u003cp>多爱自己一点和多睡一些哦～\u003c/p>\u003cp>你最亲密的IVY教练　书写于110.5.15\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>看了以上的内容，大家可能会想，呀！我不会写作文，这个太难了，简直难倒我了，很不知所措，别担心哦！这不是要你写下多么深的文采，就是让你像说话般，对自己的现况如实感知，并透过自我评分检视，排出优先顺序，学会自我提醒，不怕眼前有多难，都能有自信心向前迈进。\u003c/p>\u003cp>不要小看,这些小小举动，写给自己一封信的形式!\u003c/p>\u003cp>不要不相信，写给自己一封信的魅力！\u003c/p>\u003cp>不要怀欵，写给自己一封信的效力！\u003c/p>\u003cp>写下来是有力量的,代表你想认真看待自己的人生;代表你愿意正视问题;代表你想成为更好的自己。代表你是一位充满自信的人。\u003c/p>\u003cp>【WHERE】\u003c/p>\u003cp>此方法，适合用在人生中各种疑难杂症和困境，如：对现况不满意丶转换工作丶搬家丶买家丶租房丶工作困境等，都可以适用此方法，写下一封信给自己，当自己的人生教练，在写的过程中，自然会处处有生机。\u003c/p>","interaction":"\u003ch2>\u003cstrong>【A 学习者拆为己用】A3演練 １6分钟\u003c/strong>\u003c/h2>\u003cp>【场景设计】\u003c/p>\u003cp>好的，接下来我给⼤家1个场景，我们来做⼀个现场演练。\u003c/p>\u003cp>场景：\u003c/p>\u003cp>大美是位过了人生三十而立的职业妇人，每天上班丶下班丶照顾家庭丶照顾小孩丶照顾父母，每天总为生活丶亲人而忙，似乎没有时间好好看看自己要什麽？有什麽兴趣?有什麽梦想?随著孩子越来越大，进入了大学，渐渐地不需要她，她才发现，生活失去了重心，有种失落感；再者，长久以来的固定生活和工作，早起把大美的身心折磨到对生活只剩下家庭和工作。那个同学口中，品学兼优，生活多彩多姿，充满干劲有自信心的大美，对未来怀抱著许多的梦想的大美，如今，只剩下岁月的躯壳了\u003c/p>\u003cp>请问若你是大美的人生教练，你会用今天所学到的内容，给予大美什麽样的建议?帮助大美在尽己之责中，也能实现自我。\u003c/p>\u003cp>\u003cstrong>【A3指令】\u003c/strong>\u003c/p>\u003cp>现在我们就来试著用角色扮演大美的人生教练\u003c/p>\u003cp>Ａ是大美（当事人)\u003c/p>\u003cp>Ｂ是大美自己的教练(教练角色)\u003c/p>\u003cp>想当大美A的举手，想当B的举手\u003c/p>\u003cp>好的，我们来⽤今天学到的⽅法步骤来完成\u003c/p>\u003cp>演练时间15-20分钟，现在请开始演练。\u003c/p>\u003cp>好的，看来大家都照著本次拆页的步骤，演练好了。给大家三分钟的时间，请大家先把演练结果，记录在表格中。等会请一至二位与大家分享。\u003c/p>\u003cp>时间到了，大家都演练好了，请小伙伴与大家分享\u003c/p>\u003cp>\u003cstrong>【学习者分享的案例】\u003c/strong>\u003c/p>\u003cp>我们一起掌声~感谢小伙伴的精彩分享。\u003c/p>\u003cp>【回应】\u003c/p>\u003cp>【小组研讨】\u003c/p>\u003cp>Q：一定要两个角色扮演吗? 自己写给自己就好, 为什麽还要人格分裂假想自己是教练呢?\u003c/p>\u003cp>Ａ：感谢小伙伴的提问，这个问题很好，相信大家都会有这样的欵惑，我来解说一下，我们都很容易陷在自己的漩涡中，藉由伙伴的换位思考，帮助我们的思考更加开阔，如同拆页中提到的，想像你是你的好朋友，你的好朋友会怎麽想，会怎麽引导你。\u003c/p>\u003cp>Ｑ：最后一步骤选出大美想执行的健康方向，是不是就是指吃的部份,最重要的事?\u003c/p>\u003cp>A：是的哦，最后一步骤大美的健康方向，就是在吃的部份，去改善饮食，这样才能依据２０／８０法则，以及步骤六的重点，把时间花在刀口上，找出最重要的那一项，这样执行起来，能立即看到成效，同时也收穫自信，也就是这六步骤重要的意义。\u003c/p>\u003cp>我们再一次感谢大家的演练，以及给彼此掌声鼓励。\u003c/p>\u003cp>【反馈】（简要重复了扮演的过程， 并且号召大家鼓掌）\u003c/p>\u003cp>大家在步骤1现况时, 了解到大美在自己的健康状况出了问题, 再经过一连串地排序丶提醒丶选择丶分析丶执行后, 他也为自己的健康做出了首要执行项目-健康饮食，为大家专注演练的学习心，给予掌声鼓励；相信透过自我教练法的六步骤的方式，我们都能了解现况，当自己的贵人，先依六步骤自我引导演练后，再写下演练中的一封信，给自己信心和前进的力量。\u003c/p>\u003cp>大家演练的太好了，同时也掌握到自我教练法的六步驟技能点了，再一次给自己掌声\u003c/p>\u003ch2>【A2催化应用】\u003cstrong>11分钟\u003c/strong>\u003c/h2>\u003cp>好的，大家若没有其他的问题要提出,我们继续往下\u003c/p>\u003cp>【分步催化】\u003c/p>\u003cp>在接下来的一周或者一个月内，你在什么样的工作或生活情境下可能会需要用到自我教练的方法呢？具体的情景是怎么样的呢?具体和谁？就未來你最想专注的部份,写下时间丶情景丶和谁或者事件？写下自我教练一封信\u003c/p>\u003cp>请大家用１分钟时间来思考下！等会用2分钟来填写\u003c/p>\u003cp>１分钟时间到，现在给大家２分钟的时间写下内容，并请在组内分享完\u003c/p>\u003cp>等会请一至二位与大家分享。\u003c/p>\u003cp>\u003cstrong>【学习者分享的案例】\u003c/strong>\u003c/p>\u003cp>亲爱的卡罗：\u003c/p>\u003cp>我知道你现在正在寻找增进业馀生活的目标，这个对你的丰富学习人生非常的棒，我觉得你平时这麽喜欢追剧尤其是韩剧，何不趁著COVID-19的疫情不能出国的时期，好好的参加线上课程。一方面可以趁机学习韩文能力，\u003c/p>\u003cp>另一方面等疫情减缓可以出国时，马上就能够派上用场了，对你来说这真是个非常实用又有性有趣的计画，下个月马上就可以展开囉！\u003c/p>\u003cp>期待明年到韩国自助旅行时，可以听到你说一口流畅的旅游韩文喔！\u003c/p>\u003cp>爱你的卡罗敬上\u003c/p>\u003cp>回应与反馈：\u003c/p>\u003cp>carol的一封信,对未来想入理的领域很清楚,我们是可以简化第二步骤,因前面已经有过自我评分了,若可以,把它写上去,也能回顾。\u003c/p>\u003cp>回应与反馈：\u003c/p>\u003cp>小云的一封信，在演练时像在与人对话，我们可以把人称改为自我对话，用你是自己的教练，用&quot;你&quot;的人称来书写一封信，如同拆页中所提到的六个步骤。经反馈后,调整如下\u003c/p>\u003cp>亲爱的小云，\u003c/p>\u003cp>最近还好吗?\u003c/p>\u003cp>看到你最近的私生活还挺忙碌的，过的很常充实，\u003c/p>\u003cp>但是有时也要多花点时间陪陪孩子哦！\u003c/p>\u003cp>我看到你已经把亲密的亲子关係排在首位了，所以你开始放慢学习的脚步，关心孩子的成长了。\u003c/p>\u003cp>在人生意义和投资理财上我看到你想把看书兴趣变成收入的一年开一门线上课的计划。\u003c/p>\u003cp>希望你能早日达成目标。\u003c/p>\u003cp>有时想要太多，但现实时间有限，\u003c/p>\u003cp>所以有时也要做一些取捨，注意不要累坏身体了哦。\u003c/p>\u003cp>你看重亲密的亲子关係，因为你知道孩子已经小六，快到了父母的保存期限了。\u003c/p>\u003cp>也注意到家庭外也要爱自己所以也想把兴趣变成线上课的被动收入，兼顾人生意义和业馀生活。\u003c/p>\u003cp>我看到你也已经开始花时间经营与孩子间的亲密关係了，从日常生活中找一定会做的事，例如和孩子一起刷牙。也会花时间在孩子睡前一起谈心５分钟。\u003c/p>\u003cp>期待你和孩子都能享受美好的亲子时光。\u003c/p>\u003cp>爱你的小云敬上\u003c/p>\u003cp>\u003cstrong>【关门过渡】\u003c/strong>\u003c/p>\u003cp>通过拆页二的学习和演练，带领大家认识和体验人生自我教练法六步骤：现况丶排序丶提醒丶选择丶分析丶执行，相信大家已经有所领悟，并且学会了此方法。\u003c/p>\u003ch2>【结束语】\u003cstrong>2分钟\u003c/strong>\u003c/h2>\u003cp>对人生缺乏激情和挑战，犹如温水煮青蛙，是会让人失去自信心的，严重下，还会像儃尸，因此，我们要懂得检视自我以及随时当自我的人生教练，今天我们通过两个拆页学习到：\u003c/p>\u003cp>【总结拆页一】当我们察觉到对人生丶生活丶工作不再有热情时，我们应当用三个步骤，提醒自己；自我评分丶检视反思丶落实执行；重燃对人生丶生活丶工作的热情，用专注三领域，实现人生的梦想，让自己的未来不是梦。\u003c/p>\u003cp>【总结拆页二】当我们察觉到面对人生杂乱如麻，种种不如意之事，犹如排山倒海而来，我们可以透过自我教练法六步骤：现况丶排序丶提醒丶选择丶分析丶执行，重燃对生活丶工作丶未来的自信心，找到最适合自己的节奏。\u003c/p>\u003cp>【关门结束】\u003c/p>\u003cp>今天的二个拆页，到此结束，感谢大家。期望大家皆能在自我评分三方法和自我教练六步骤中，实现所设计的目标。祝大家都能掌控人生，实现梦想！谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1632473072000,"updated_at":1634192753000,"ria":true},{"id":12167,"topic":"从舒适圈跨出对生活和工作的自我反思并以自评方式找到人生想专注的三领域;当遇到挫折时,能够当人生的自我教练,来让自信心充满力量，面对一切困扰，实现未来不是梦。","learn_goal":"","remark":"在跟随我完成RIA现场学习后，学习者能够透过拆页一，构建人生目标中，找到专注的三个领域，将愿景细分和聚焦；并且透过拆页二，当面对当前人生决择时的错综複染问题，不再慌张失措，透过六步骤写下给自己的一封信中，，从信中从容找到解决之道,成为人生的自我教练。","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"ivywang","city":""},"club":{"name":"台北悦读不卡分舵","city":"台北"},"prologue":"\u003cp>\u003cstrong>【问好+分组】1分钟\u003c/strong>\u003c/p>\u003cp>大家好，我是IVY，来自台湾台北的王靖蕙。我的三个标签：劲量电池丶开创行者丶值得信赖,欢迎参加我的2-4练级场，今天的学习有许多演练环节，现在分组一下,就依大家现在坐的位置，我的左手边是一组，右手边是二组。\u003c/p>\u003ch2>\u003cstrong>【图书介绍】2分钟\u003c/strong>\u003c/h2>\u003cp>【F】今天我要给大家介绍的这本书《自信力：成为最好的自己》作者：英国-罗布.杨博士是顶尖的商业演讲家,心理学权威人士，本书分为二大部份，自信力成就最好的自己和生活处处是自信，是本帮助我们举手投足和在人生每个时刻都能拥有自信力的一本好书。透过这本书的现场拆书,将使你从容不迫,面对挫折和难解之题，找到最好的解决之道,向最好的自己迈进。\u003c/p>\u003cp>【A】与其他同类书籍相比，这本书裡面的自信力助进器非常简要又好实作，除了作者本身是心理学权威外，本书也提到许多案例，可说是有案例有方法，令人看过后，易执行且获得好自信的好方法。今日的二则拆页内容，皆来自这本书的自信力助进器，可谓是本实践类的好书。\u003c/p>\u003cp>【B1】这本书教你面对人生中种种的问题，运用自信力助进器的方法,从容不迫面对各种疑难杂症，找到最妥善的面对之道。此书里都有方法，让我们找到解决问题的答案，成為人生的主人翁。\u003c/p>\u003cp>【B2】今天这两个拆页讲的是，在舒适圈中，面对生活工作不再激情与活力，如何重燃人生干劲，立下人生专注三领域，落实执行；当面对挫折不顺时，如何透过自我教练六步骤，再度迎刃而解，成为自己的人生教练，做自己的人生设计师。\u003c/p>\u003cp>\u003cstrong>【拆页一学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成拆页一的RIA现场学习后，学习者能够：\u003c/p>\u003cp>在面对生活丶人生缺乏激情和挑战等时,更有自信心去专注重要三个领域上，并实现想要的生活，聚焦在愿景上。构建自己的未来目标。\u003c/p>","ratings_count":2,"texts":[{"id":16079,"quote":"\u003cp>\u003cstrong>【R阅读拆页一】1分钟\u003c/strong>\u003c/p>\u003cp>來源：《自信力.成为最好的自己》（第3版）微信电子书 你的未來就是夢 P263-264\u003c/p>\u003cp>27岁的卡特已经在网络游戏公司担任软件工程师多年。他拥有舒适的生活，但是他觉得自己的生活缺乏激情和挑战。\u003c/p>\u003cp>然而，现在他不再有这种感觉。虽然他兴趣广泛，但是他决定专注于三个特别的领域，在这些领域中他对自己的表现不太满意。他写出了自己的初步目标。\u003c/p>\u003cp>·我的健康状况：我的身体正在变得虚弱无力，我的同事杰西卡（Jessica）说我有了啤酒肚。我想通过健身和减肥，让自己的身体重获健康与活力。\u003c/p>\u003cp>·我的职业生涯：我想拓展我的工作范围，而不是日复一日去完成同样枯燥的任务。我喜欢我的工作，但我不能违心地说这份工作激发了我的热情和斗志。我想找一份新的工作，做一些新鲜的事情，并且沉浸其中。我甚至可以辞职创业。\u003c/p>\u003cp>·我的经济状况：我想在接下来的几年里买一套房子。对于现在来说这是不可能的，我没有足够的储蓄，只能租房住，所以我会找理财顾问谈谈，了解我可以借多少钱，制订一个理财计划。今年我可能还无法购买房子，但是我一定会在年底前制订理财计划。\u003c/p>","explains":"\u003cp>\u003cstrong>I 拆书家讲解引导 \u003c/strong>６分钟\u003c/p>\u003cp>好，我看到大家已经看完拆页了，接下来我就分享一下我的理解和体会。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>舒适生活丶兴趣广泛丶工作繁複，一成不变，大约是现今的普遍现象，这是一篇，要我们展望未来的一个实例，要我們不要固守现况，而要去构建想要实现的目标，专注在三个领域上。如：健康丶职业丶经济状况。\u003c/p>\u003cp>【意译案例】根据原书中案例脉络，给出更贴近实际的例子。\u003c/p>\u003cp>40岁多的IVY已经在不动产公司担任会计一职多年。她拥有稳定又离家近的的生活，但是她觉得自己的生活缺乏一些激情和挑战。\u003c/p>\u003cp>然而，现在她不再有这种感觉。虽然她什麽都想学，兴趣广泛，但是她决定专注于三个特别的领域，在这些领域中，她对自己的表现不太满意。她写出了自己的初步目标。\u003c/p>\u003cp>·我的健康状况：我的身体正在变得肿胀如牛，气力如同小兔，我的好友大圣说我有了游泳圈。我想通过跑步和健身，让自己的身体重获活力朝气和健康。\u003c/p>\u003cp>·我的职业生涯：我想挑战我的工作范围，而不是天天都做著枯燥繁锁的任务。我喜欢我现在的这一份工作，但我不能违心地说这份工作有给我热情和斗志。我想在现有的工作中，做一些新鲜的事情，并且沉浸其中。我甚至可以在职创业。\u003c/p>\u003cp>·我的经济状况：我想在接下来的几年里买一间二人房。对于现在来说这是不可能的，因为我没有足够的储蓄，只能租房住，因此我会去找理财顾问谈谈，了解我可以借多少钱，制订一个理财计划。也许今年我可能还无法购买房子，但是我一定会在今年底前制订理财计划，按步就班实施有屋族。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>为什么要用这样的方式检视自己来实现想要的生活如此重要呢?没有人会希望生活是一成不变的，都会期望精彩可期，人不可能一辈子都在固有模式下生活，因此要勇于去构建未来想过的生活。让这一生不致于空过一生，同时可以自信迎接。\u003c/p>\u003cp>【2-1强调不这么做的坏处（失败的经验）】\u003c/p>\u003cp>如果我们固守现况，不乐意改变，我们的人生就没有其他可能，这一生，就这样渡过了，但若我们愿意突破现况，给自己一些时间专注在三领域中，未来必会不遗憾此生。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>那要如何做呢?当我们还不知从何入理三领域时,我们可以先来这样做？\u003c/p>\u003cp>1.自我评分\u003c/p>\u003cp>首先想下自己现在的工作和生活满意度\u003c/p>\u003cp>并根据工作和生活满意度,在八个领域表格中自我评分，１—１０分的满意分,1分最低,10分最高\u003c/p>\u003cp> 2.检视反思\u003c/p>\u003cp>评分好了之后,分出高分和低分,低分代表自信力低,没有被满足的地方,也是你内心渴望完成的部份;高分代表目前为止,是自信做的还不错的地方。\u003c/p>\u003cp>3.落实方向\u003c/p>\u003cp>人生的精力有限，因此你要从自我评分表中，去选出三个领域，可以改变未来短期一年内，能够实现愿望的领域，你可以高低分搭配。也可以全低分丶全高分搭配，主要还是你自己想要过得更自信为主。\u003c/p>\u003cp>如同案例中，写出你的三领域的初步目标\u003c/p>\u003cp>【列举反例】失败案例\u003c/p>\u003cp>学校毕业后的我，以为学到一技之长就够了，进入社会，上班下班，不思进取，浑浑噩噩渡过了好几十年的黑白人生，宅女阿肥是我的代表词。\u003c/p>\u003cp>【加工成正例】\u003c/p>\u003cp>直到有一次我去看了一场白日梦冒险王电影之后，我开始正视自己的人生，觉得自己跟电影中的男主角好像，因我们都是当会计；当时开始期许自己的未来人生，不要再是黑白，要变精彩；开始跨出学习丶开始在没有尝试过的领域前进，如爬山丶游泳丶跑步等领域前进\u003c/p>\u003cp>我的人生变的不同了，我变瘦了丶我变的有气质了丶我变的有自信了，同时更对未来充满期许，原来我的潜力如此之大，自己都觉得不可思议。\u003c/p>\u003cp>【反思】\u003c/p>\u003cp>如果当时我没有藉由电影自我评分现况,我还是一样宅在家，没有走出去，我可能一辈子，就活在自己的井字天空。检视反思才能开拓,若没有落实执行,更无法站在这儿与大家分享了。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能有人会想，评分检示，我不想评耶！我的人生看来没有什麽问题！！！要我评，办不到。无法懂得自我评分的人生，是没有自信的代表，这是逃避而非面对,因为，每个人,这一生都会有想要去的地方丶想要完成的事丶或者想给人幸福的能力。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这个方法，很适合用在检视现况，以及想创造未来的方向上，当我们对生活缺乏激情丶索然无味和挑战时，可以用自我评分丶检视反思丶落实行动这方法，来使自己对未来有期待，让未来不是梦，得以实现。\u003c/p>","interaction":"\u003cp>【A1激活经验】５分钟\u003c/p>\u003cp>回忆一下，你最近半年，有没有遇到像拆页一人物卡特,对健康丶职涯丶经济状况充满不确定性的担忧，对未来没有期待。请大家先就这三个在组内分享，然后再想一个领域最想入理的部份,等会我们后面会一起演练自我教练的部份。\u003c/p>\u003cp>时间为１—２分钟，请大家在小组讨论一下，一会也会请小伙伴分享一下。\u003c/p>\u003cp>\u003cstrong>【学习者分享的案例】\u003c/strong>\u003c/p>\u003cp>洪：自评结果,八大面向平均分约满意六分，在不确定的健康丶职涯丶经济领域中,都会担忧,选一个先执行的话，最想维持好体态，可以再减５公斤。\u003c/p>\u003cp>王：自评结果,八大面向平均分约满意七分，在不确定的健康丶职涯丶经济领域中,都会担忧,选一个先执行的话，最想多增加财务的状况，每月再多存5000元,增加被动收入。\u003c/p>\u003cp>拆页一我们学习了，如何对现况自我评分？并且检视反思，同时落实执行，为自己构建未来的目标，相信大家的未来都不是梦 ,并能逐梦而踏实。而在过程中，我们不可能时时都会遇到贵人助我们一把，或者有人可以请益，因此我们接下来的拆页二学习，就是当我们对目标有坚持不下去时，可以用自我教练的方式，当自己的人生贵人。\u003c/p>\u003cp>下面我们就来学习拆页二。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":16080,"quote":"\u003cp>\u003cstrong>【拆页二学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成拆页二的RIA现场学习后，学习者能够运用“做自己教练6步法”完成一封给自己的信，进行现场应用，从而提升自信力。\u003c/p>\u003ch2>\u003cstrong>【R阅读拆页二】2分钟\u003c/strong>\u003c/h2>\u003cp>来源：自信力：成为最好的自己（第3版）微信电子书p407\u003c/p>\u003cp>自信力助推器：做自己的教练\u003c/p>\u003cp>想象你是你的一位好朋友，给你写了一封信，帮助你分析当前的情况，指出你有哪些选择，最后提出合适的解决问题的办法。在信的开头一定要写上“亲爱的XX（你自己的名字）”，然后按照下面的步骤来写。\u003c/p>\u003cp>1.明确当前的问题或困境。找一张干净的纸，然后在上面描述出当前的情况。不要担心不知道该写什么，只要动手写就可以了，比如“我看到你现在的情况是……”。也许你写了几句话之后，突然有了灵感，后面要写什么也就顺理成章地写出来了。在写的过程中，要记得描述发生了什么事情以及你有什么感受。\u003c/p>\u003cp>2.列举可能的选择。把所有可能解决当前困难的办法都写下来。即便是对那些非黑即白、非此即彼的问题，你也可以在极端的办法之间找到很多灵活变通的方法。比如说，当你和配偶的婚姻关系出现问题时，除了选择继续在一起或者永远地分开以外，还可以选择暂时分居或是接受婚姻咨询服务。如果暂时分居，还可以选择到朋友家去住上几个星期，也可以自己找房子住半年。只要稍微想一想，你就会有比最初多得多的想法。\u003c/p>\u003cp>3.权衡利弊。写下每一种办法的利与弊，以及这些办法给你的感受。通过权衡利弊，你能够很轻易地找出哪些办法最有建设性。\u003c/p>\u003cp>4.向前一小步。摆脱非此即彼的视角，重新审视你的现状，你可能就会发现自己应该前进的方向了。\u003c/p>\u003cp>很多人都在选择方向的时候无所适从，因为他们不知道哪种选择是对的。但是如果一直犹豫不决，这只会让你停滞不前。结果，看起来你好像还没有做出选择，但其实你已经选择了放弃。\u003c/p>\u003cp>行动本身就意味着进步。如果你不喜欢自己选择的事，至少你也知道了自己不喜欢什么。如果发现自己做了错误的决定，至少你也知道了正确答案不是这个。只要你做出决定，便会知道下一步该做些什么，不论是做什么，都比什么也不做要好。\u003c/p>\u003cp>在你的信中，有你对当前发生事情的描述，也有你对这些事情感受的描述，既有事实又有情感。这样做的原因是当你将自己的感受也考虑在内时，能够找到更有效的解决办法。曾经有研究者调查了一群被解雇的人，发现那些写下自己失业感受的人，比那些没有写过感受的人能更快地找到新工作。写感受并不是为了释放情绪而采用的空洞技术，它确实能够提供给人们更有效的解决办法。所以为了让自己更好地应对困境，记得不光要写事实，还要写感受。\u003c/p>","explains":"\u003ch2>\u003cstrong>【I讲解】６分钟\u003c/strong>\u003c/h2>\u003cp>好，我看到大家已经看完拆页了，接下来我就分享一下我的理解和体会。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>这是把自己当成自己的好朋友丶好教练,在面对困境时，用有效的解決步驟,來使你有自信心去迎接它，完成自己的愿望和目标，不受困难或挫败问题所影响而前置不前的好方法。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>为什么要学此方法?人生中，不可能一帆风顺，当遇到不如意或者挫折以及複杂的问题时，我们就能透过自我教练法，在人生的这些时刻中，做自己的主人。可说是成为自己贵人的好方法。\u003c/p>\u003cp>【How】那么，要如何来写这封信呢？准备一张纸，开头写下：\u003c/p>\u003cp>亲爱的IVY：\u003c/p>\u003cp>看到你为自己设下专注在三个领域（健康丶图卡+写作丶理财)上，如此弘大且实践路上的目标,很为你感到开心,同时相信,你会知道,接下来你要面对的困境和问题,会是什么?\u003c/p>\u003cp>1.现况：描述当前情况（问题丶事实丶感受丶情感都可以写)\u003c/p>\u003cp>你说，工作太忙丶下班后要学习丶执行线上课以及制卡，已分身乏术，实在无法再学习＂写作&quot;新的领域。\u003c/p>\u003cp>2.排序：排列优先顺序\u003c/p>\u003cp>我建议你，面对如此多的情况，先从八大面向自我评分一下，再来排列优先顺序\u003c/p>\u003cp> 从高至低排列\u003c/p>\u003cp>职业生涯\u003c/p>\u003cp>健康状况\u003c/p>\u003cp>人生意义\u003c/p>\u003cp>家庭生活\u003c/p>\u003cp>业馀生活\u003c/p>\u003cp>社交生活\u003c/p>\u003cp>投资理财\u003c/p>\u003cp>亲密关係\u003c/p>\u003cp>3提醒：写下自我提醒\u003c/p>\u003cp>看来你的分数和想专注的三领域上，一比较后，最弱的是投资理财，而非写作，是不是要想下，写作真的是你现在的当务之急吗?\u003c/p>\u003cp>4.选择：选择可行事项\u003c/p>\u003cp>请你静下心来，运用检视反思的回顾，在这三领域以及八大面向中，你真正想专注的是什麽？想好后，重新做选择\u003c/p>\u003cp>健康资本\u003c/p>\u003cp>学习领域：图卡\u003c/p>\u003cp>投资理财\u003c/p>\u003cp>5.分析：分析所选项目\u003c/p>\u003cp>健康资本：健康是本，无法运动的时期，良好的睡眠和在家做伸展和深蹲\u003c/p>\u003cp>学习领域：图卡搭配想在开发的领域，如投资理财\u003c/p>\u003cp>投资理财：以把自己的财务，理好为优先，收入—储蓄＝支出\u003c/p>\u003cp>6.执行:选出重要执行\u003c/p>\u003cp>当你明白了时间和精力，以及健康的重要，要有好脑力，请从现在起，每天睡足６—７小时，千万不要再熬夜，没有好体力，就没有好脑力，更无法把想做的任务完成哦。请以健康的基础下，完成另二个领域，健康是本，记得睡眠充足很重要，不可轻忽。\u003c/p>\u003cp>多爱自己一点和多睡一些哦～\u003c/p>\u003cp>你最亲密的IVY教练　书写于110.5.15\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>看了以上的内容，大家可能会想，呀！我不会写作文，这个太难了，简直难倒我了，很不知所措，别担心哦！这不是要你写下多么深的文采，就是让你像说话般，对自己的现况如实感知，并透过自我评分检视，排出优先顺序，学会自我提醒，不怕眼前有多难，都能有自信心向前迈进。\u003c/p>\u003cp>不要小看,这些小小举动，写给自己一封信的形式!\u003c/p>\u003cp>不要不相信，写给自己一封信的魅力！\u003c/p>\u003cp>不要怀欵，写给自己一封信的效力！\u003c/p>\u003cp>写下来是有力量的,代表你想认真看待自己的人生;代表你愿意正视问题;代表你想成为更好的自己。代表你是一位充满自信的人。\u003c/p>\u003cp>【WHERE】\u003c/p>\u003cp>此方法，适合用在人生中各种疑难杂症和困境，如：对现况不满意丶转换工作丶搬家丶买家丶租房丶工作困境等，都可以适用此方法，写下一封信给自己，当自己的人生教练，在写的过程中，自然会处处有生机。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3促动参与】１７分钟\u003c/strong>\u003c/p>\u003ch2>\u003cstrong>【A 学习者拆为己用】A3演練 １７分钟\u003c/strong>\u003c/h2>\u003cp>【场景设计】\u003c/p>\u003cp>好的，接下来我给⼤家1个场景，我们来做⼀个现场演练。\u003c/p>\u003cp>场景：\u003c/p>\u003cp>大美是位过了人生三十而立的职业妇人，每天上班丶下班丶照顾家庭丶照顾小孩丶照顾父母，每天总为生活丶亲人而忙，似乎没有时间好好看看自己要什麽？有什麽兴趣?有什麽梦想?随著孩子越来越大，进入了大学，渐渐地不需要她，她才发现，生活失去了重心，有种失落感；再者，长久以来的固定生活和工作，早起把大美的身心折磨到对生活只剩下家庭和工作。那个同学口中，品学兼优，生活多彩多姿，充满干劲有自信心的大美，对未来怀抱著许多的梦想的大美，如今，只剩下岁月的躯壳了\u003c/p>\u003cp>请问若你是大美的人生教练，你会用今天所学到的内容，给予大美什麽样的建议?帮助大美在尽己之责中，也能实现自我。\u003c/p>\u003cp>\u003cstrong>【A3指令】\u003c/strong>\u003c/p>\u003cp>现在我们就来试著用角色扮演大美的人生教练\u003c/p>\u003cp>Ａ是大美（当事人)\u003c/p>\u003cp>Ｂ是大美自己的教练(教练角色)\u003c/p>\u003cp>想当大美A的举手，想当B的举手\u003c/p>\u003cp>好的，我们来⽤今天学到的⽅法步骤来完成\u003c/p>\u003cp>演练时间15-20分钟，现在请开始演练。\u003c/p>\u003cp>好的，看来大家都照著本次拆页的步骤，演练好了。给大家三分钟的时间，请大家先把演练结果，记录在表格中。等会请一位与大家分享。\u003c/p>\u003cp>【小组研讨】\u003c/p>\u003cp>下面请大家在小组内讨论，刚才的过程，如果有疑问还可以举手问我。\u003c/p>\u003cp>【学员的问题与拆书家回应】\u003c/p>\u003cp>Q1：是要全部都低分的项目吗?\u003c/p>\u003cp>A1：可以高低分配，也可以全部都高分或低分，主要是自己想专注的领域。\u003c/p>\u003cp>Q2：大美和教练要怎麽开始?\u003c/p>\u003cp>A2：从HＯＷ的部份来观看，依照六步骤来完成，开头是教练先引导，先说＂亲爱的大美，最近有遇到什麽的困扰吗?可以从问题丶现况丶感受来说一说&quot;\u003c/p>\u003cp>Q3：教练要帮大美做决定吗?\u003c/p>\u003cp>A3：教练负责引导大美来说出他的想法和自评结果，不用帮大美决定，而是引导让她去看见自己真正想做的是什麽，可以实现未来不是梦的愿望。\u003c/p>\u003cp>【回应】（拆书家先简要重述了3个问题，然后回答：）\u003c/p>\u003cp>这是提问的三个Q，一一回覆说明如上。\u003c/p>\u003cp>【反馈】（简要重复了扮演的过程， 并且号召大家鼓掌）\u003c/p>\u003cp>时间到了，二组都演练好了，都有一一帮大美找到想做的吗?\u003c/p>\u003cp>太好了，我们为自己掌声一下。相信透过这样的方式，当我们还没有遇到贵人时，就可以先当自己的贵人，先自我引导演练一下。\u003c/p>\u003cp>\u003cstrong>【学习者分享的案例】\u003c/strong>\u003c/p>\u003cp>【A2催化应用】１０分钟\u003c/p>\u003cp>好的，大家若没有其他的问题要提出,我们继续往下\u003c/p>\u003cp>【分步催化】\u003c/p>\u003cp>在接下来的一周或者一个月内，你在什么样的工作或生活情境下可能会需要用到自我教练的方法呢？具体的情景(可以是拆页一讲到的场景：健身丶理财丶开课等)是怎么样的呢?具体和谁？就刚刚你最想专注的部份,写下时间丶情景丶和谁或者事件？写下自我教练一封信\u003c/p>\u003cp>请大家用１分钟时间来思考下！等会用2分钟来填写\u003c/p>\u003cp>时间到，现在给大家２分钟的时间写下内容。并请在组内分享完\u003c/p>\u003cp>等会请一至二位与大家分享。\u003c/p>\u003cp>\u003cstrong>【学习者分享的案例】\u003c/strong>\u003c/p>\u003cp>案例一:\u003c/p>\u003cp>亲爱的麒富：\u003c/p>\u003cp>身为你的好友，我知道你很重视身体健康，也因工作的关系，你也很重视面对客户时呈现的良好形象，由于现在台湾的疫情不稳定，你长期待在家里开始横向发展，而你也表明目标要再瘦个5KG。\u003c/p>\u003cp>控制好体重会让你看起来更有自信也更年轻，真高兴你随着成长还是不断地要求自己，通过记录体重的变化，来衡量自己的状况，能在家落实目标的方案有作燃脂运动（TABATA），少吃零食，喝奶昔等方式，其中我相信作燃脂运动是最适合你的，因为既可减重又能锻炼肌肉，因此每天15分钟的训练必不可少。\u003c/p>\u003cp>期待自律的你在10月底前达成目标，因而变的更有自信，加油，我相信你一定可以达到自己想要的样子。\u003c/p>\u003cp>你的好友 麒富上\u003c/p>\u003cp>案例二:\u003c/p>\u003cp>亲爱的March\u003c/p>\u003cp>我知道你一直关心你的财务状况，希望有足够的被动收入达到财务自由的目标，让你能自由的去想做的事情。\u003c/p>\u003cp>要财务自由除了在本业多赚点钱外，投资也是个好方法。你今年再度检视自己人生大领域的重要性，财务依旧是你最关心的议题之一。\u003c/p>\u003cp>工作多年，虽然没有达到财务自由的状况，但总是有点累积，积沙总会成塔的。想要透过被动收入让自己财务自由，可以做的事情有三项:1.订阶段目标(如:让被动收入达到月薪金额，先从每年一个月开始)2.定期存股3.纪录被动收入效能。\u003c/p>\u003cp>这三个选项中最重要的是订目标，把财务自由的目标用被动收入达到月薪的方式，将目标分成12份，慢慢去累积。\u003c/p>\u003cp>有纪律、快速的存股，你总有一天会有足够的被动收入让你自由～\u003c/p>\u003cp>你最亲密的March教练　书写于1100814\u003c/p>\u003cp>\u003cstrong>【关门过渡】\u003c/strong>\u003c/p>\u003cp>通过拆页二的学习和演练，带领大家认识和体验人生自我教练法六步骤：现况丶排序丶提醒丶选择丶分析丶执行，相信大家已经有所领悟，并且学会了此方法。\u003c/p>\u003ch2>【结束语】 1分钟\u003c/h2>\u003cp>对人生缺乏激情和挑战，犹如温水煮青蛙，是会让人失去自信心的，严重下，还会像儃尸，因此，我们要懂得检视自我以及随时当自我的人生教练，今天我们通过两个拆页学习到：\u003c/p>\u003cp>【总结拆页一】当我们察觉到对人生丶生活丶工作不再有热情时，我们应当用三个步骤，提醒自己；自我评分丶检视反思丶落实执行；重燃对人生丶生活丶工作的热情，用专注三领域，实现人生的梦想，让自己的未来不是梦。\u003c/p>\u003cp>【总结拆页二】当我们察觉到面对人生杂乱如麻，种种不如意之事，犹如排山倒海而来，我们可以透过自我教练法六步骤：现况丶排序丶提醒丶选择丶分析丶执行，重燃对生活丶工作丶未来的自信心，找到最适合自己的节奏。\u003c/p>\u003cp>【关门结束】\u003c/p>\u003cp>今天的二个拆页，到此结束，感谢大家。祝大家都能掌控人生，实现梦想！谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1629387580000,"updated_at":1634989969000,"ria":true},{"id":11872,"topic":"腹式呼吸","learn_goal":"","remark":"人的心理与身体是相互影响的。当我们承受压力时，呼吸频率就会加快，属浅式呼吸，空气只充满肺部顶端部分，我们便开始喘息。\n但是，我们也可以通过改变呼吸方式来使大脑产生自信的感受。在自然呼吸的状态下，我们使用的是位于肚脐下方的一个结缔组织片——横膈膜。\n因此，一旦学会腹式呼吸，你就可以平复消极情绪。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"海川","city":""},"club":{"name":"南宁清澄分舵","city":"南宁"},"prologue":"\u003cp>欢迎各位小伙伴，大家上午好，我是海川，接下来由我带领大家进行‘腹式呼吸’ 主题的拆解，下面我们分一下组，方便一会相互分享。\u003c/p>\u003cp>‘腹式呼吸’ 这个拆页来自《自信力》这本书的117页。\u003c/p>\u003cp>F：特性\u003c/p>\u003cp>《自信力》是一本能帮你提升自信的好书。作者罗布·杨教授现在是一位享誉全球的资深心理培训专家，但他也曾是一位因缺乏自信而饱受折磨的人。\u003c/p>\u003cp>A：优势\u003c/p>\u003cp>相比其它的谈自信力的书籍，本书既有作者自我的亲身经历，也有从事心里培训的专业背景，书中很多方法都运用了精湛的心理培训技巧，能够让读者更容易的实践和操作。\u003c/p>\u003cp>B：利益\u003c/p>\u003cp>你可能都有过这样的经历，因为缺乏自信，而错失了很多次改变的机会，或者一次重要的演讲，或者一次关乎幸福的表白，通过阅读和实践通过改变呼吸方式来使大脑产生自信的感受 这种全新的方法，相信我们能从中获得启发，更好的掌控自己的人生。\u003c/p>\u003cp>学习目标：\u003c/p>\u003cp>1、在跟随我完成本次RIA学习后，现场的学习者能够自己用教给的动作腹式呼吸。\u003c/p>\u003cp>2、现场的学习者能说出腹式呼吸的对情绪的正向影响及动作。\u003c/p>","ratings_count":1,"texts":[{"id":15822,"quote":"\u003cp>自信力：成为最好的自己 P117 页\u003c/p>\u003cp>人的心理与身体是相互影响的。当我们承受压力时，呼吸频率就会加快，属浅式呼吸，空气只充满肺部顶端部分，我们便开始喘息。但是，我们也可以通过改变呼吸方式来使大脑产生自信的感受。在自然呼吸的状态下，我们使用的是位于肚脐下方的一个结缔组织片——横膈膜。因此，一旦学会腹式呼吸，你就可以平复消极情绪。\u003c/p>\u003cp>\u003cstrong> 你可以在家里按照如下步骤练习腹式呼吸。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、把右手放在胸膛上，左手放在肚脐处。轻轻地吸一口气，就好像你在闻空气中一种好闻的味道一样，或者猛吸一口气，就好像你在吸鼻涕一样。此时，你可以感受到自己的左手在动，你的腹部就在那儿。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2、现在慢慢地深吸一口气，使空气充满整个肺部。你的左手在你吸气时上升，在你呼气时下降，而你的右手应该一直保持不动。慢慢地呼吸四下。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3、重复几分钟后，你会觉得非常放松。当你的身体放松，血液流向全身各处时，你的手指和脚趾就会开始暖和起来。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请在感觉放松的时候练习腹式呼吸并养成腹式呼吸的习惯。如此一来，一旦遇到紧急情况需要腹式呼吸时，你就可以迅速转换到这种呼吸模式。很多人在压力大时都会选择抽烟。然而，托尼·施瓦兹（Tony Schwartz）和凯瑟琳·麦卡锡（Catherine McCarthy）的研究发现，深呼吸更能有效缓解压力，而不必吸入满肺的浓烟。\u003c/strong>\u003c/p>","explains":"\u003cp>这个拆页讲的是腹式呼吸的一种方法，这种方法可以有效的缓解紧张的情绪和压力。\u003c/p>\u003cp>what：\u003c/p>\u003cp>腹式呼吸，顾名思义，是通过腹部的运动进行呼吸，是一种深度呼吸的方法。它让横膈膜上下移动。由于吸气时横膈膜会下降，把脏器挤到下方，因此肚子会膨胀，而非胸部膨胀。因此，吐气时横膈膜将会比平常上升，因而可以进行深度呼吸，吐出较多易停滞在肺底部的\u003ca href=\"https://baike.baidu.com/item/%E4%BA%8C%E6%B0%A7%E5%8C%96%E7%A2%B3/349143\">二氧化碳。\u003c/p>\u003cp>可以想象一下，你的肚子是一个气球，吸气的时候就像一股气流通过导管吹入气球，气球就会向四周膨胀。\u003c/p>\u003cp>腹式呼吸的关键是：无论是吸还是呼都要尽量达到“极限”量，即吸到不能再吸，呼到不能再呼为度；同理，腹部也要相应收缩与胀大到极点，如果每口气直达下\u003ca href=\"https://baike.baidu.com/item/%E4%B8%B9%E7%94%B0\">丹田则更好。\u003c/p>\u003cp>why：\u003c/p>\u003cp>腹式呼吸对肺部来说是一种很好的保健方法。经常练习能够有效的缓解紧张和焦虑情绪、增加氧气供给量、改善睡眠、降血压。\u003c/p>\u003cp>how：\u003c/p>\u003cp>怎么进行腹式呼吸呢，我演示一下：\u003c/p>\u003cp>1、把右手放在胸膛上，左手放在肚脐处。轻轻地吸一口气，就好像你在闻空气中一种好闻的味道一样，或者猛吸一口气，就好像你在吸鼻涕一样。此时，你可以感受到自己的左手在动，你的腹部就在那儿。\u003c/p>\u003cp>2、现在慢慢地深吸一口气，使空气充满整个肺部。你的左手在你吸气时上升，在你呼气时下降，而你的右手应该一直保持不动。慢慢地呼吸四下。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>、这样重复几分钟分钟，你会觉得非常放松。当你的身体放松，血液流向全身各处时，你的手指和脚趾就会开始暖和起来。\u003c/p>\u003cp>开始的时候我们每天可以练习5-6分钟，慢慢习惯之后，每天可以增加练习时间。\u003c/p>\u003cp>Where：\u003c/p>\u003cp>腹式呼吸练习一般在身体相对比较安静的状态下进下。\u003c/p>\u003cp>记得我之前有一次去客户现场做产品演示，演示之前，我特别恐慌，心跳加速，血液流动很快，手心发冷，身体处于亢奋状态，走路都感觉有点飘，脑子里各种消极的念头。\u003c/p>\u003cp>这个时候我们通常的做法是，去跟脑子里的各种消极念头搏斗，去否定这些念头，刚冒出来PPT做的不够好，好像有个重要的数据还缺乏依据，就逮住这个念头，跟它打架，自我催眠式的告诉自己，做的很好了。然而，负面的念头终不肯认输，头脑成为了一片狼藉的战场，自己也完全失去了智力。\u003c/p>\u003cp>如果当时我用腹式呼吸，把所有的注意力集中在气流从鼻腔到气管到肺部，流变全身时的身体感受，集中在腹部的起伏之上，那当时的紧张的情绪马上便会得到缓解，不至于情绪奔溃。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：显像提问设计\u003c/strong>：小伙伴们有没有经历过这样的时刻，在某一天，你参加面试，等待面试官的到来，或者第一次见丈母娘，心里七上八下，不知道会面临怎样的审讯，有没有感受过，如果你也是这样的感受，那么，这个时候你是不是很想平复下自己纷乱紧张情绪，你在这样的情境下是如何处理这样的感受的呢？或者有没有过因为太过于紧张，而逃避的情况呢？\u003c/p>\u003cp>案例整理：\u003c/p>\u003cp>学习者Andy分享了她在上周头马俱乐部演讲的一次经历：\u003c/p>\u003cp>到她上台演讲的过程中，因为紧张没有被处理，心里一直忐忑不安，在讲到一个重要的观点的时候，突然忘词了，忘记了这个观点接下来的要举的列子了，从来没有遇到过这样的突发状况，不知道该如何处理，紧张的快要奔溃了，后来磕磕绊绊的把演讲草草结束了。非常遗憾。\u003c/p>\u003cp>\u003cstrong>A1+反思加工：\u003c/strong>提问设计：假如时间可以穿越的话，要是再回到当时的现场，你运用刚刚学到的方法，该如何去回应呢？\u003c/p>\u003cp>案例整理：\u003c/p>\u003cp>Andy 分享了她穿越回当时现场之后，她运用腹式呼吸的做法重新应对当演讲的情况。在演讲之前利用腹式呼吸，把注意力都专注在自己的呼吸之上，而不去关注头脑中各种消极的声音，提升自己的自信力，并且允许一切发生，相信演讲会表现的更好。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1625582177000,"updated_at":1626187009000,"ria":true}]};